# WARNING: check this before any log file is opened so the crash and VLC logs of the process that triggered the relaunch survive.
_IS_RELAUNCH = "--relaunched" in sys.argv

def _clear_stale_logs_on_fresh_boot():
    if _IS_RELAUNCH:
        return
    _dir = _log_output_dir()
    for _name, _prev_name in (("crash_log.txt", "crash_log_previous.txt"),
                               ("vlc-debug.log", "vlc-debug_previous.log")):
        try:
            os.replace(os.path.join(_dir, _name), os.path.join(_dir, _prev_name))
        except FileNotFoundError:
            pass
        except Exception as e:
            try:
                sys.stderr.write(
                    f"[BOOT] could not rotate {_name} to {_prev_name}: {e}\n")
            except Exception:
                pass

_clear_stale_logs_on_fresh_boot()

