def _is_true_43_hardware():
    """Whether Windows is running a real 4:3 display mode, as opposed to the fake-4:3 test mode inside a 16:9 window."""
    try:
        return bool(db is not None and getattr(db, "_detected_aspect_ratio", None) == "4:3")
    except Exception:
        return False


def _get_channel_visualizer_style(ch_conf):
    """Return a channel's effective visualizer style from its saved config."""
    return (ch_conf or {}).get("visualizer_style", "Random")


def _read_boot_fullscreen_pref():
    # WARNING: an auto-relaunch (crash, heartbeat stall, post-update) always boots fullscreen, whatever kiosk_mode_enabled / start_on_boot say.
    if _IS_RELAUNCH:
        return True
    try:
        _cfg_path = os.path.join(os.path.dirname(os.path.abspath(sys.argv[0])), "retro_config.json")
        if os.path.exists(_cfg_path):
            import json as _json
            with open(_cfg_path, "r") as _f:
                _cfg = _json.load(_f).get("config", {})
            _kiosk = _cfg.get("kiosk_mode_enabled", False)
            _boot  = _cfg.get("start_on_boot", False)
            return bool(_kiosk or _boot)
    except Exception as _boot_pref_err:
        log.warning(f"Could not read boot display prefs, defaulting to windowed: {_boot_pref_err}")
    return False


def _compute_boot_window_size(native_w, native_h, aspect):
    if aspect == "4:3":
        target_w, target_h = 1024, 768
    else:
        target_w, target_h = 1280, 720

    max_w = max(320, native_w - 80)
    max_h = max(240, native_h - 80)
    if target_w > max_w or target_h > max_h:
        _scale = min(max_w / target_w, max_h / target_h)
        target_w = max(1, int(target_w * _scale))
        target_h = max(1, int(target_h * _scale))
    return target_w, target_h


def _set_window_topmost(win_hwnd, topmost):
    """Windows-only: pin or unpin this window above all others in z-order, including transient shell popups such as AutoPlay."""
    if sys.platform != "win32" or not win_hwnd:
        return
    try:
        HWND_TOPMOST   = -1
        HWND_NOTOPMOST = -2
        SWP_NOMOVE     = 0x0002
        SWP_NOSIZE     = 0x0001
        SWP_NOACTIVATE = 0x0010
        ctypes.windll.user32.SetWindowPos(
            win_hwnd, HWND_TOPMOST if topmost else HWND_NOTOPMOST,
            0, 0, 0, 0,
            SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE)
    except Exception as _topmost_err:
        log.warning(f"[WINDOW] Could not set topmost={topmost}: {_topmost_err}")


def _start_autoplay_dismisser():
    """Windows-only: watch for the AutoPlay dialog and close it as soon as it appears."""
    if sys.platform != "win32":
        return

    def _watch():
        WNDENUMPROC = ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.c_void_p, ctypes.c_void_p)
        WM_CLOSE = 0x0010

        def _enum_callback(hwnd, _lparam):
            try:
                if not ctypes.windll.user32.IsWindowVisible(hwnd):
                    return True
                length = ctypes.windll.user32.GetWindowTextLengthW(hwnd)
                if length == 0:
                    return True
                buf = ctypes.create_unicode_buffer(length + 1)
                ctypes.windll.user32.GetWindowTextW(hwnd, buf, length + 1)
                # WARNING: match only the exact "AutoPlay" dialog title so nothing unrelated is ever closed.
                if buf.value.strip().lower() == "autoplay":
                    print(f"[AUTOPLAY GUARD] AutoPlay dialog detected (hwnd={hwnd}) -- closing it.")
                    ctypes.windll.user32.PostMessageW(hwnd, WM_CLOSE, 0, 0)
            except Exception as _cb_err:
                log.warning(f"[AUTOPLAY GUARD] Enum callback error: {_cb_err}")
            return True

        _callback = WNDENUMPROC(_enum_callback)
        while True:
            try:
                ctypes.windll.user32.EnumWindows(_callback, 0)
            except Exception as _enum_err:
                _log_warn_throttled("rtv_L855", f"[AUTOPLAY GUARD] EnumWindows error: {_enum_err}")
            time.sleep(0.75)

    threading.Thread(target=_watch, daemon=True, name="AutoPlayGuard").start()
    print("[AUTOPLAY GUARD] Watcher thread started.")


def _restore_windowed_maximize_box(win_hwnd):
    if sys.platform != "win32" or not win_hwnd:
        return
    try:
        GWL_STYLE        = -16
        WS_MINIMIZEBOX   = 0x00020000
        WS_MAXIMIZEBOX   = 0x00010000
        WS_SYSMENU       = 0x00080000
        WS_THICKFRAME    = 0x00040000
        SWP_NOZORDER     = 0x0004
        SWP_NOMOVE       = 0x0002
        SWP_NOSIZE       = 0x0001
        SWP_FRAMECHANGED = 0x0020

        style = ctypes.windll.user32.GetWindowLongW(win_hwnd, GWL_STYLE)
        style |= (WS_MAXIMIZEBOX | WS_MINIMIZEBOX | WS_SYSMENU)
        style &= ~WS_THICKFRAME
        ctypes.windll.user32.SetWindowLongW(win_hwnd, GWL_STYLE, style)
        ctypes.windll.user32.SetWindowPos(
            win_hwnd, 0, 0, 0, 0, 0,
            SWP_NOZORDER | SWP_NOMOVE | SWP_NOSIZE | SWP_FRAMECHANGED)
    except Exception as _style_err:
        log.warning(f"[WINDOW] Could not restore maximize box: {_style_err}")


def _win32_window_is_zoomed(win_hwnd):
    """Return whether a decorated Windows window is natively maximized."""
    if sys.platform != "win32" or not win_hwnd:
        return False
    try:
        return bool(ctypes.windll.user32.IsZoomed(win_hwnd))
    except Exception:
        return False


def _get_window_client_size():
    """Read the drawable client area after Windows maximizes the window."""
    if sys.platform == "win32":
        try:
            win_hwnd = pygame.display.get_wm_info().get("window")
            if win_hwnd:
                class _RECT(ctypes.Structure):
                    _fields_ = [("left", ctypes.c_long), ("top", ctypes.c_long),
                                ("right", ctypes.c_long), ("bottom", ctypes.c_long)]
                rect = _RECT()
                if ctypes.windll.user32.GetClientRect(win_hwnd, ctypes.byref(rect)):
                    client_w = max(1, int(rect.right - rect.left))
                    client_h = max(1, int(rect.bottom - rect.top))
                    return client_w, client_h
        except Exception as _client_err:
            _log_warn_throttled("window_client_size", "[WINDOW] Could not read maximized client size: %s", _client_err)
    try:
        return tuple(int(v) for v in pygame.display.get_window_size())
    except Exception:
        return int(WINDOW_WIDTH), int(WINDOW_HEIGHT)


def _get_primary_work_area():
    """Return the desktop work area, excluding the Windows taskbar."""
    try:
        class _RECT(ctypes.Structure):
            _fields_ = [("left", ctypes.c_long), ("top", ctypes.c_long),
                        ("right", ctypes.c_long), ("bottom", ctypes.c_long)]
        rect = _RECT()
        if ctypes.windll.user32.SystemParametersInfoW(
                0x0030, 0, ctypes.byref(rect), 0):
            return int(rect.left), int(rect.top), int(rect.right), int(rect.bottom)
    except Exception as _work_area_err:
        log.warning(f"[WINDOW] Could not read desktop work area: {_work_area_err}")
    return 0, 0, int(NATIVE_WIDTH), int(NATIVE_HEIGHT)


def _get_window_outer_rect(win_hwnd):
    if sys.platform != "win32" or not win_hwnd:
        return None
    try:
        class _RECT(ctypes.Structure):
            _fields_ = [("left", ctypes.c_long), ("top", ctypes.c_long),
                        ("right", ctypes.c_long), ("bottom", ctypes.c_long)]
        rect = _RECT()
        if ctypes.windll.user32.GetWindowRect(win_hwnd, ctypes.byref(rect)):
            return int(rect.left), int(rect.top), int(rect.right), int(rect.bottom)
    except Exception as _outer_rect_err:
        log.warning(f"[WINDOW] Could not read outer window rectangle: {_outer_rect_err}")
    return None


def _ensure_window_really_maximized(win_hwnd):
    """Repair a native maximize that changed the button but not geometry."""
    if sys.platform != "win32" or not win_hwnd:
        return
    try:
        left, top, right, bottom = _get_primary_work_area()
        work_w = max(1, right - left)
        work_h = max(1, bottom - top)
        outer = _get_window_outer_rect(win_hwnd)
        if outer is not None:
            outer_w = outer[2] - outer[0]
            outer_h = outer[3] - outer[1]
            if outer_w >= work_w - 8 and outer_h >= work_h - 8:
                return

        ctypes.windll.user32.SetWindowPos(
            win_hwnd, 0, left, top, work_w, work_h,
            0x0004 | 0x0020 | 0x0040,
        )
        ctypes.windll.user32.ShowWindow(win_hwnd, 3)
    except Exception as _ensure_max_err:
        log.warning(f"[WINDOW] Could not repair maximized geometry: {_ensure_max_err}")


def _resize_windowed_surface_to_client(screen):
    """Resize the Pygame surface without switching to borderless fullscreen."""
    global WINDOW_WIDTH, WINDOW_HEIGHT
    client_w, client_h = _get_window_client_size()
    WINDOW_WIDTH, WINDOW_HEIGHT = client_w, client_h
    try:
        screen = _set_display_mode((client_w, client_h), pygame.RESIZABLE)
    except Exception as _resize_err:
        log.warning(f"[WINDOW] Could not resize maximized windowed surface: {_resize_err}")
    if sys.platform == "win32":
        try:
            _restore_windowed_maximize_box(pygame.display.get_wm_info().get("window"))
        except Exception as _style_err:
            log.warning(f"[WINDOW] Could not restore maximized windowed style: {_style_err}")
    return screen


def _restore_fixed_windowed_surface(screen):
    """Return to the app's fixed, centered window after taskbar restore."""
    global WINDOW_WIDTH, WINDOW_HEIGHT
    fixed_w, fixed_h = _compute_boot_window_size(
        NATIVE_WIDTH, NATIVE_HEIGHT, DETECTED_ASPECT_RATIO
    )
    WINDOW_WIDTH, WINDOW_HEIGHT = fixed_w, fixed_h
    try:
        screen = _set_display_mode((fixed_w, fixed_h))
    except Exception as _fixed_resize_err:
        log.warning(f"[WINDOW] Could not restore fixed window surface: {_fixed_resize_err}")

    if sys.platform == "win32":
        try:
            win_hwnd = pygame.display.get_wm_info().get("window")
            if win_hwnd:
                ctypes.windll.user32.ShowWindow(win_hwnd, 9)
        except Exception as _fixed_restore_err:
            log.warning(f"[WINDOW] Could not restore fixed window state: {_fixed_restore_err}")

    fixed_x = max(0, (NATIVE_WIDTH - fixed_w) // 2)
    fixed_y = max(0, (NATIVE_HEIGHT - fixed_h) // 2)
    _finalize_window_mode(
        screen, windowed=True,
        client_w=fixed_w, client_h=fixed_h,
        pos_x=fixed_x, pos_y=fixed_y,
    )
    return screen


def _maximize_windowed_surface(screen):
    """Maximize the decorated window, then fit the surface to its client area."""
    win_hwnd = None
    if sys.platform == "win32":
        try:
            win_hwnd = pygame.display.get_wm_info().get("window")
            if win_hwnd:
                # WARNING: do not restore first or force through (0, 0); that flashes the top-left instead of the grow-from-place maximize.
                if not _win32_window_is_zoomed(win_hwnd):
                    ctypes.windll.user32.ShowWindow(win_hwnd, 3)
                pygame.event.pump()
                _ensure_window_really_maximized(win_hwnd)
        except Exception as _native_max_err:
            log.warning(f"[WINDOW] Could not natively maximize window: {_native_max_err}")

    screen = _resize_windowed_surface_to_client(screen)

    if sys.platform == "win32":
        try:
            win_hwnd = pygame.display.get_wm_info().get("window")
            if win_hwnd:
                _restore_windowed_maximize_box(win_hwnd)
                ctypes.windll.user32.ShowWindow(win_hwnd, 3)
                _ensure_window_really_maximized(win_hwnd)
                _client_w, _client_h = _get_window_client_size()
                log.info("[WINDOW] Maximized windowed geometry: hwnd=%s client=%sx%s zoomed=%s",
                         win_hwnd, _client_w, _client_h,
                         _win32_window_is_zoomed(win_hwnd))
        except Exception as _native_rem_max_err:
            log.warning(f"[WINDOW] Could not reassert native maximized window: {_native_rem_max_err}")
    return screen


def _finalize_window_mode(screen, *, windowed, client_w, client_h, pos_x, pos_y):
    if sys.platform == "win32":
        try:
            win_hwnd = pygame.display.get_wm_info().get("window")
            if win_hwnd:
                SWP_NOZORDER     = 0x0004
                SWP_FRAMECHANGED = 0x0020
                SWP_SHOWWINDOW   = 0x0040
                GWL_STYLE, GWL_EXSTYLE = -16, -20

                if windowed:
                    _restore_windowed_maximize_box(win_hwnd)

                out_w, out_h = client_w, client_h
                if windowed:
                    class _RECT(ctypes.Structure):
                        _fields_ = [("left", ctypes.c_long), ("top", ctypes.c_long),
                                    ("right", ctypes.c_long), ("bottom", ctypes.c_long)]
                    rect = _RECT(0, 0, int(client_w), int(client_h))
                    style   = ctypes.windll.user32.GetWindowLongW(win_hwnd, GWL_STYLE)
                    exstyle = ctypes.windll.user32.GetWindowLongW(win_hwnd, GWL_EXSTYLE)
                    dpi = 96
                    try:
                        dpi = ctypes.windll.user32.GetDpiForWindow(win_hwnd) or 96
                    except Exception:
                        dpi = 96
                    _ok = False
                    try:
                        _ok = bool(ctypes.windll.user32.AdjustWindowRectExForDpi(
                            ctypes.byref(rect), ctypes.c_ulong(style), False,
                            ctypes.c_ulong(exstyle), ctypes.c_uint(dpi)))
                    except Exception:
                        _ok = False
                    if not _ok:
                        try:
                            _ok = bool(ctypes.windll.user32.AdjustWindowRectEx(
                                ctypes.byref(rect), ctypes.c_ulong(style), False,
                                ctypes.c_ulong(exstyle)))
                        except Exception:
                            _ok = False
                    if _ok:
                        out_w = rect.right - rect.left
                        out_h = rect.bottom - rect.top

                ctypes.windll.user32.SetWindowPos(
                    win_hwnd, 0, int(pos_x), int(pos_y), int(out_w), int(out_h),
                    SWP_NOZORDER | SWP_FRAMECHANGED | SWP_SHOWWINDOW)

                _set_window_topmost(win_hwnd, topmost=not windowed)
        except Exception as pos_err:
            log.warning(f"[WINDOW] Could not finalize window mode: {pos_err}")

    try:
        pygame.event.pump()
        screen.fill((0, 0, 0))
        _present_cpu_window()
        pygame.event.pump()
    except Exception as present_err:
        log.warning(f"[WINDOW] Could not present frame after mode switch: {present_err}")


