def _apply_mixer_channels_setting():
    """Reopen pygame.mixer with the channel count the Mono Audio toggle calls for (1 = mono, 2 = stereo), read fresh from db.config["audio_stereo"]."""
    desired = 1 if (db is not None and not db.config.get("audio_stereo", True)) else 2
    try:
        _current = pygame.mixer.get_init()
    except Exception:
        _current = None
    if _current is not None and _current[2] == desired:
        return
    try:
        pygame.mixer.music.stop()
    except Exception:
        pass
    try:
        pygame.mixer.quit()
        pygame.mixer.pre_init(44100, -16, desired, 2048)
        pygame.mixer.init()
        log.info("[SETTINGS] pygame.mixer reopened with channels=%d (Mono Audio=%s).",
                 desired, desired == 1)
    except Exception as e:
        log.warning("[SETTINGS] pygame.mixer channel reinit failed (staying on previous "
                    "channel count): %s", e)

try:
    pygame.mixer.set_reserved(3)
except Exception as _reserve_err:
    log.warning(f"pygame.mixer.set_reserved(3) failed: {_reserve_err}")

def resource_path(rel_path):
    parts = rel_path.split(os.sep)
    if parts and parts[0] == "main":
        return os.path.join(resolve_main_dir(), *parts[1:])
    try:
        meipass = getattr(sys, "_MEIPASS", None)
        if meipass:
            return os.path.join(meipass, rel_path)
    except Exception as e:
        log.warning("resource_path: _MEIPASS lookup failed for %s: %s", rel_path, e)
    return os.path.join(os.path.dirname(os.path.abspath(__file__)), rel_path)


_tv_border_cache = {}
_TV_BORDER_MTIME_RECHECK_TTL_SEC = 2.0
_tv_border_mtime_recheck_state = {}
_tv_border_current_path = {"path": None}
_tv_border_raw_preload = {}
_tv_border_raw_preload_lock = threading.Lock()


