def _bezel_file_cache_key(path):
    """Return a stable cache key that survives raw->display surface conversion."""
    if not path:
        return None
    try:
        return (os.path.normcase(os.path.abspath(path)), os.path.getmtime(path))
    except Exception:
        return (os.path.normcase(os.path.abspath(path)), 0)


_bezel_cache_key_state = {}


def _bezel_file_cache_key_throttled(path):
    """Return the (norm_path, mtime) bezel cache key with the os.path.getmtime() re-stat throttled to once per _TV_BORDER_MTIME_RECHECK_TTL_SEC per path."""
    if not path:
        return None
    now = time.monotonic()
    cached = _bezel_cache_key_state.get(path)
    if cached is not None and now < cached[0]:
        return cached[1]
    key = _bezel_file_cache_key(path)
    _bezel_cache_key_state[path] = (now + _TV_BORDER_MTIME_RECHECK_TTL_SEC, key)
    return key


def _real_screen_is_true_169(win_w, win_h):
    """Whether the real (Windows-reported) screen is actually 16:9-shaped, a stricter test than DETECTED_ASPECT_RATIO's closer-to-16:9-than-4:3."""
    if not win_h:
        return False
    return abs((win_w / win_h) - (16.0 / 9.0)) < 0.02


def _effective_bezel_style_count(win_w, win_h):
    """How many bezel styles are actually selectable right now."""
    n = len(discover_bezel_style_files())
    if n == 0:
        return 1
    if n > 1 and not _real_screen_is_true_169(NATIVE_WIDTH, NATIVE_HEIGHT):
        n -= 1
    return max(1, n)


def _resolve_current_bezel_path(win_w=None, win_h=None):
    bezel_dir = resolve_bezel_dir()
    numbered = discover_bezel_style_files()
    if numbered:
        eligible = numbered
        # WARNING: the wood-cabinet art (stem "bezel2") only fits a real 16:9 screen and must stay hidden on any other shape.
        if (win_w is not None and win_h is not None and len(numbered) > 1
                and not _real_screen_is_true_169(NATIVE_WIDTH, NATIVE_HEIGHT)):
            eligible = [p for p in numbered
                        if os.path.splitext(os.path.basename(p))[0].lower() != "bezel2"]
            if not eligible:
                eligible = numbered
        if not eligible:
            return None
        style_idx = db.config.get("bezel_style", 1) if db is not None else 1
        try:
            style_idx = int(style_idx)
        except (TypeError, ValueError):
            style_idx = 1
        style_idx = max(1, min(style_idx, len(eligible)))
        return eligible[style_idx - 1]
    if os.path.isdir(bezel_dir):
        exact = os.path.join(bezel_dir, "bezel.png")
        if not os.path.isfile(exact):
            exact = os.path.join(bezel_dir, "border.png")
        if os.path.isfile(exact):
            return exact
        exts = (".png", ".jpg", ".jpeg", ".bmp", ".gif")
        try:
            for f in sorted(os.listdir(bezel_dir)):
                if os.path.splitext(f)[1].lower() in exts:
                    return os.path.join(bezel_dir, f)
        except Exception as e:
            log.warning("_resolve_current_bezel_path: could not list %s: %s", bezel_dir, e)
    return None


def _load_bezel_surface_from_path(path):
    """Load (or return cached) surface for a specific bezel image path."""
    if path is None:
        return None
    now = time.monotonic()
    cached = _tv_border_cache.get(path)
    _next_check = _tv_border_mtime_recheck_state.get(path, 0.0)
    if cached is not None and now < _next_check:
        return cached[1]
    try:
        mtime = os.path.getmtime(path)
    except Exception:
        mtime = 0
    _tv_border_mtime_recheck_state[path] = now + _TV_BORDER_MTIME_RECHECK_TTL_SEC
    cache_key = (path, mtime)
    if cached is not None and cached[0] == cache_key:
        return cached[1]

    try:
        with _tv_border_raw_preload_lock:
            preloaded = _tv_border_raw_preload.pop(path, None)
        raw_surf = preloaded.convert_alpha() if preloaded is not None else pygame.image.load(path).convert_alpha()
    except Exception as e:
        log.warning(f"[4:3 BEZEL] Could not load bezel image '{path}': {e}")
        _tv_border_cache.pop(path, None)
        return None

    _tv_border_cache[path] = (cache_key, raw_surf)
    return raw_surf


def _preload_games_tab_logos():
    """Warm every Games-tab console logo off the render thread so opening the Menu is instant."""
    try:
        import os
        from game_deck import CONSOLE_ORDER
    except Exception as e:
        log.warning("_preload_games_tab_logos: could not import CONSOLE_ORDER: %s", e)
        return
    logos_dir = os.path.join(media.resolve_main_dir(), "images", "logos")
    for console_key in CONSOLE_ORDER:
        logo_path = os.path.join(logos_dir, f"{console_key}.png")
        try:
            if not os.path.exists(logo_path):
                continue
            raw = pygame.image.load(logo_path)
            cropped = ui._crop_logo_to_artwork(raw)
            with ui._games_tab_logo_raw_preload_lock:
                ui._games_tab_logo_raw_preload[console_key] = cropped
        except Exception as e:
            log.warning("_preload_games_tab_logos: failed to warm '%s': %s", logo_path, e)


def _preload_all_bezel_styles():
    """Warm every discovered numbered bezel style off the render thread so switching styles is instant."""
    try:
        numbered = discover_bezel_style_files()
    except Exception as e:
        log.warning("_preload_all_bezel_styles: discovery failed: %s", e)
        return
    for path in numbered:
        try:
            raw = pygame.image.load(path)
            with _tv_border_raw_preload_lock:
                _tv_border_raw_preload[path] = raw
            try:
                _bezel_key = _bezel_file_cache_key(path)
                _full_tv_border_cutout_frac(raw, _bezel_key, border_path=path)
            except Exception as _analysis_err:
                log.warning(
                    "_preload_all_bezel_styles: analysis failed for '%s': %s",
                    path, _analysis_err)
        except Exception as e:
            log.warning("_preload_all_bezel_styles: failed to warm '%s': %s", path, e)


