_watermark_cache = {"path": None, "raw": None, "target_w": None, "surface": None}

_watermark_transition_state = {}
# VALUES CHANGE HERE
_WATERMARK_JUMP_TOLERANCE_PX = 2
_WATERMARK_REPOSITION_HIDE_MS = 450
_WATERMARK_ALPHA = 150
_WATERMARK_WIDTH_FRAC = 0.091
_WATERMARK_MARGIN_FRAC = 0.12

_WATERMARK_BEZEL_EXTRA_OFFSET = {
    "bezel":  (10, 10),
    "bezel1": (10, 10),
    "bezel2": (10, 10),
}


def _is_live_tv_broadcast_channel(ch):
    """Return True for the real over-the-air TV channels (05-44), False for ch03 and ch04."""
    # WARNING: static noise, reception lines and the watermark all share this one test; keep it that way so they never disagree on what counts as live TV.
    try:
        return ch not in ("03", "04") and 5 <= int(ch) <= 44
    except (TypeError, ValueError):
        return False


def _draw_watermark(screen, bounds_rect=None, apply_bezel_offset=True, state_key="main"):
    """Draw the semi-transparent station-bug image in the bottom-right corner of the window."""
    path = db.config.get("watermark_path", "") if db is not None else ""
    if not path:
        path = DEFAULT_WATERMARK_PATH
    if not path or not os.path.isfile(path):
        return
    try:
        if bounds_rect is not None:
            ox, oy, sw, sh = bounds_rect.x, bounds_rect.y, bounds_rect.width, bounds_rect.height
        else:
            ox, oy = 0, 0
            sw, sh = screen.get_size()
        if sw <= 0 or sh <= 0:
            return

        _wm_state = _watermark_transition_state.setdefault(
            state_key, {"last_rect": None, "hide_until": 0})
        _wm_now = pygame.time.get_ticks()
        _wm_cur_rect = (ox, oy, sw, sh)
        _wm_prev_rect = _wm_state["last_rect"]
        if _wm_prev_rect is not None and any(
                abs(_wm_cur_rect[i] - _wm_prev_rect[i]) > _WATERMARK_JUMP_TOLERANCE_PX
                for i in range(4)):
            _wm_state["hide_until"] = _wm_now + _WATERMARK_REPOSITION_HIDE_MS
        _wm_state["last_rect"] = _wm_cur_rect
        if _wm_now < _wm_state["hide_until"]:
            return

        target_w = max(24, int(sw * _WATERMARK_WIDTH_FRAC))
        cache = _watermark_cache

        if cache["path"] != path:
            loaded = None
            try:
                loaded = pygame.image.load(path).convert_alpha()
            except Exception as _load_err:
                try:
                    _decoded = pygame.image.load(path)
                    loaded = _decoded.convert_alpha()
                except Exception as _load_err2:
                    print(f"[WATERMARK] Failed to load watermark image "
                          f"'{os.path.basename(path)}': {_load_err2}")
                    log.warning("[WATERMARK] Could not load %s: %s (retry: %s)",
                                path, _load_err, _load_err2)
            # WARNING: record the attempt even on failure; cache["raw"] is False marks a known-bad image, and without it the load is retried every frame.
            cache["raw"] = loaded if loaded is not None else False
            cache["path"] = path
            cache["target_w"] = None

        raw = cache["raw"]
        if raw is False:
            return
        if cache["target_w"] != target_w or cache["surface"] is None:
            raw_w, raw_h = raw.get_size()
            if raw_w <= 0 or raw_h <= 0:
                return
            target_h = max(1, int(raw_h * (target_w / raw_w)))
            scaled = pygame.transform.smoothscale(raw, (target_w, target_h))
            faded = scaled.copy()
            alpha_arr = pygame.surfarray.pixels_alpha(faded)
            alpha_arr[:] = (alpha_arr.astype(np.uint16) * _WATERMARK_ALPHA // 255).astype(np.uint8)
            del alpha_arr
            cache["surface"] = faded
            cache["target_w"] = target_w

        margin_x = max(6, int(sw * _WATERMARK_MARGIN_FRAC))
        margin_y = max(6, int(sh * _WATERMARK_MARGIN_FRAC))
        extra_x = 0.0
        extra_y = 0.0
        if apply_bezel_offset:
            _stem = _active_bezel_stem_if_on()
            if _stem is not None:
                extra_x, extra_y = _WATERMARK_BEZEL_EXTRA_OFFSET.get(_stem, (0, 0))
        wm_rect = cache["surface"].get_rect(bottomright=(
            ox + sw - margin_x - int(extra_x),
            oy + sh - margin_y - int(extra_y),
        ))
        screen.blit(cache["surface"], wm_rect)
    except Exception as e:
        log.warning("_draw_watermark: draw failed: %s", e)


_STARTUP_REG_PATH = r"Software\Microsoft\Windows NT\CurrentVersion\Winlogon"
_STARTUP_REG_NAME = "Shell"
_DEFAULT_SHELL = "explorer.exe"

_LEGACY_STARTUP_REG_PATH = r"Software\Microsoft\Windows\CurrentVersion\Run"
_LEGACY_STARTUP_REG_NAME = "RetroTVEmulator"


# ============================================================================
# SECTION: Start-on-boot & deferred settings save
# ============================================================================


def _get_startup_command():
    if getattr(sys, "frozen", False):
        return f'"{sys.executable}" --as-shell'
    return f'"{sys.executable}" "{os.path.abspath(__file__)}" --as-shell'


def _launch_explorer_fallback():
    if os.name != "nt":
        return
    try:
        subprocess.Popen(["explorer.exe"])
    except Exception as e:
        log.warning(f"[STARTUP] Could not launch explorer.exe fallback: {e}")


def _set_start_on_boot(enabled):
    if os.name != "nt":
        print("[STARTUP] Not running on Windows — start-on-boot toggle has no effect here.")
        return False
    try:
        import winreg
        try:
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER, _LEGACY_STARTUP_REG_PATH, 0, winreg.KEY_SET_VALUE) as legacy_key:
                try:
                    winreg.DeleteValue(legacy_key, _LEGACY_STARTUP_REG_NAME)
                except FileNotFoundError:
                    pass
        except FileNotFoundError:
            pass

        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, _STARTUP_REG_PATH, 0, winreg.KEY_SET_VALUE) as key:
            if enabled:
                winreg.SetValueEx(key, _STARTUP_REG_NAME, 0, winreg.REG_SZ, _get_startup_command())
            else:
                winreg.SetValueEx(key, _STARTUP_REG_NAME, 0, winreg.REG_SZ, _DEFAULT_SHELL)
        return True
    except Exception as e:
        log.warning(f"[STARTUP] Failed to {'enable' if enabled else 'disable'} start-on-boot: {e}")
        return False


def _mark_settings_dirty():
    now = pygame.time.get_ticks()
    if not app_state.get("_settings_dirty", False):
        app_state["_settings_dirty_first"] = now
    app_state["_settings_dirty"] = True
    app_state["_settings_dirty_since"] = now


def _flush_settings_if_dirty(force=False):
    if db is None or not app_state.get("_settings_dirty", False):
        return
    now = pygame.time.get_ticks()
    quiet_elapsed = now - app_state.get("_settings_dirty_since", now)
    total_elapsed = now - app_state.get("_settings_dirty_first", now)
    if force or quiet_elapsed > 400 or total_elapsed > 1500:
        db.save_settings_async(force=force)
        app_state["_settings_dirty"] = False


