_GAME_CORE_FPS_FALLBACK = 60.0
_GAME_CORE_FPS_GUARD = (40.0, 120.0)
_UI_COMPOSITOR_FPS = 60.0


def _feature_locked(config_key):
    """True while the current performance mode greys out and switches off this setting."""
    try:
        return performance_governor is not None and performance_governor.feature_locked(config_key)
    except Exception:
        return False


def _setting_on(config_key, default=False):
    """The setting's value as the app applies it: always off while the current performance mode locks it."""
    if db is None or _feature_locked(config_key):
        return False
    return bool(db.config.get(config_key, default))


def _lite_menu_screen_active(game_deck_ref):
    """True while a menu, list or guide screen is showing (not video, not a launched game)."""
    if (app_state.get("show_menu", False) or app_state.get("show_splash", False)
            or app_state.get("show_quit_confirm", False) or app_state.get("show_restart_confirm", False)
            or app_state.get("file_explorer_active", False)):
        return True
    if app_state.get("current_channel") == "04":
        return True
    return (game_deck_ref is not None
            and getattr(game_deck_ref, "mode", None) in ("BROWSE", "ROMLIST")
            and app_state.get("current_channel") == "03")


def _resolve_main_loop_tick_fps(game_deck_ref):
    """Return the clock.tick() rate that paces the main loop for the current mode."""
    # WARNING: do not lower _UI_COMPOSITOR_FPS to match the video; video is not tied to this tick, so it only makes input and overlay redraws choppier.
    if (game_deck_ref is not None
            and getattr(game_deck_ref, "mode", None) == "GAME"
            and getattr(game_deck_ref, "_libretro_core", None) is not None
            and not getattr(game_deck_ref, "emulator_loading", False)):
        try:
            core_fps = float(game_deck_ref._libretro_core.fps)
            lo, hi = _GAME_CORE_FPS_GUARD
            if lo <= core_fps <= hi:
                return core_fps
        except Exception as e:
            _log_warn_throttled(
                "core_fps_tick_pacing",
                "Per-frame core.fps lookup for tick pacing failed, using %.1f: %s",
                _GAME_CORE_FPS_FALLBACK, e)
        return _GAME_CORE_FPS_FALLBACK
    try:
        _menu_cap = performance_governor.menu_fps() if performance_governor is not None else 0.0
        if _menu_cap > 0.0 and _lite_menu_screen_active(game_deck_ref):
            return min(_UI_COMPOSITOR_FPS, _menu_cap)
    except Exception:
        pass
    return _UI_COMPOSITOR_FPS

