def _start_guide_preview_load(hl_ch, hl_state):
    """Starts a guide-preview VLC load of hl_ch/hl_state's file, or registers the failure for a confirmed-dead channel."""
    _gp_dead_root = _station_confirmed_dead_drive.get(hl_ch)
    if _gp_dead_root is not None and _drive_confirmed_recovered(_gp_dead_root):
        _station_confirmed_dead_drive.pop(hl_ch, None)
        _clear_broken_files_for_root(_gp_dead_root)
        _gp_dead_root = None
    if _gp_dead_root is not None:
        app_state["loaded_preview_path_cache"] = hl_state["file"]
        app_state["guide_preview_loading"] = False
        _register_channel_playback_failure(
            hl_ch, hl_state["file"],
            duration=hl_state.get("duration"), block=hl_state.get("block"),
        )
        return
    try:
        vlc_engine.player.audio_set_mute(True)
    except Exception:
        pass
    app_state["_video_pending_unmute"] = True
    vlc_engine.stop()
    # WARNING: do not add a fixed startup pad; buffering time varies, so it would make every guide preview seek inaccurate.
    _VLC_STARTUP_LATENCY_S = 0.0

    def _gp_on_confirmed(success, attempt_id, deferred,
                          _hl_ch=hl_ch, _hl_state=dict(hl_state)):
        if success:
            _confirm_playback_started(
                _hl_ch, attempt_id, _hl_state["file"],
                _hl_state.get("seek", 0) + _VLC_STARTUP_LATENCY_S,
                _hl_state.get("seek_slot_offset", 0),
                _hl_state.get("duration", 1800),
                _hl_state.get("mode", "Video"),
                _hl_state.get("block", "Morning"),
                _hl_state.get("interior_cut", False),
                deferred,
            )
        else:
            _confirm_playback_failed(_hl_ch, attempt_id, _hl_state.get("file"), deferred,
                                      reason="guide_preview_open_failed")

    app_state["last_video_play_started_at"] = pygame.time.get_ticks()
    vlc_engine.play_file_segmented(
        hl_state["file"],
        hl_state["seek"],
        gain=_lookup_file_gain(hl_ch, hl_state["file"]),
        defer_unmute=True,
        on_confirmed=_gp_on_confirmed,
    )
    _mute_guard_log("ARM (guide preview load)", ch=hl_ch, filepath=hl_state["file"])
    app_state["loaded_preview_path_cache"] = hl_state["file"]
    app_state["guide_preview_loading"] = True
    app_state["guide_preview_load_started_ms"] = pygame.time.get_ticks()


def _arm_warm_transition_shield(engine, burst_ms):
    """Covers a guide warm-continuation switch (ch05 <-> the guide previewing ch05) with the configured Transition Type, without touching playback."""
    try:
        engine.player.audio_set_mute(True)
    except Exception:
        pass

    def _do_unmute():
        time.sleep(max(0, burst_ms - 1) / 1000.0)
        try:
            engine.player.audio_set_mute(False)
        except Exception:
            pass

    import threading as _t
    _t.Thread(target=_do_unmute, daemon=True).start()


def _arm_guide_preview_transition():
    _transition_style = db.config.get("transition_type", "black") if db is not None else "black"
    if _transition_style == "static":
        app_state["guide_preview_black_until"] = 0
        app_state["guide_preview_static_until"] = pygame.time.get_ticks() + STATIC_TRANSITION_MS
    else:
        app_state["guide_preview_static_until"] = 0
        app_state["guide_preview_black_until"] = pygame.time.get_ticks() + GUIDE_PREVIEW_SETTLE_MS
    app_state["guide_preview_settle_until"] = pygame.time.get_ticks() + GUIDE_PREVIEW_SETTLE_MS

    app_state["loaded_preview_path_cache"] = ""
    app_state["guide_preview_loading"] = False
    app_state["guide_preview_load_started_ms"] = 0

    if pygame.mixer.music.get_busy():
        pygame.mixer.music.stop()
    app_state["music_owner"] = ""
    app_state["guide_preview_music_track"] = ""

    if vlc_engine is not None and getattr(vlc_engine, "player", None) is not None:
        try:
            vlc_engine.player.audio_set_mute(True)
        except Exception:
            pass
    app_state["_video_pending_unmute"] = True
    _governor_note_event("guide_row_switch")
    _mute_guard_log("ARM (guide row switch)", ch=app_state.get("highlighted_guide_channel"))

_GUIDE_HL_STATE_REFRESH_MS = 1000

_GUIDE_HL_STATE_HOLD_MS = 8000


def _capture_guide_preview_position(ch_key):
    """Save the exact position of the preview before surfing to another row."""
    ch_key = str(ch_key).zfill(2)
    if ch_key != str(app_state.get("_live_playback_channel", "")).zfill(2):
        return
    if vlc_engine is None or getattr(vlc_engine, "player", None) is None:
        return
    try:
        current_ms = vlc_engine.player.get_time()
        current_media = vlc_engine.player.get_media()
        current_mrl = current_media.get_mrl() if current_media else ""
        if current_ms is None or current_ms < 0 or not current_mrl:
            return
        from urllib.parse import unquote as _unquote_preview
        current_file = os.path.normpath(
            _unquote_preview(current_mrl.replace("file:///", "")))
        # WARNING: only save a position when the engine is playing the file this channel was last confirmed on; during a deferred open the engine already holds the next channel's file.
        _confirmed_anchor = (db.channels_db.get(ch_key, {}).get("playback_anchor") or {}) if db is not None else {}
        _confirmed_file = _confirmed_anchor.get("file") if isinstance(_confirmed_anchor, dict) else None
        if (not _confirmed_file
                or os.path.normcase(os.path.normpath(str(_confirmed_file))) != os.path.normcase(current_file)
                or not _file_in_channel_schedule(ch_key, _confirmed_file)):
            return
        now_ticks = pygame.time.get_ticks()
        preview_cache = app_state.setdefault("_guide_preview_position_cache", {})
        preview_cache[ch_key] = {
            "file": current_file,
            "seek": current_ms / 1000.0,
            "duration": max(1.0, (vlc_engine.player.get_length() or 0) / 1000.0),
            "captured_ticks": now_ticks,
        }
    except Exception as _preview_snapshot_err:
        log.debug("guide preview position snapshot unavailable: %s", _preview_snapshot_err)


def _get_guide_hl_playback_state(ch_key, slot="hl"):
    ch_key = str(ch_key).zfill(2)
    now_ticks = pygame.time.get_ticks()

    preview_cache = app_state.get("_guide_preview_position_cache", {})
    preview_resume = preview_cache.get(ch_key)
    if preview_resume and preview_resume.get("file"):
        _resume_seek = preview_resume.get("seek", 0) + (
            now_ticks - preview_resume.get("captured_ticks", now_ticks)
        ) / 1000.0
        _resume_dur = preview_resume.get("duration", 0)
        if _resume_dur > 1.0 and _resume_seek < _resume_dur:
            resumed = dict(preview_resume)
            resumed["mode"] = (
                "Commercial"
                if _is_commercial_file_for_channel(ch_key, preview_resume["file"])
                else "Video"
            )
            resumed["seek"] = _resume_seek
            resumed["block"] = ""
            return resumed
        preview_cache.pop(ch_key, None)

    _live_ch_now = app_state.get("_live_playback_channel", "")
    if _live_ch_now and ch_key == str(_live_ch_now).zfill(2):
        return calculate_slotted_playback_state(ch_key)

    cache_key = f"_guide_hl_state_cache_{slot}"
    cache = app_state.get(cache_key)
    if cache is not None and cache.get("ch") == ch_key:
        age_ms = now_ticks - cache.get("ts", -_GUIDE_HL_STATE_HOLD_MS)
        cached_state = cache.get("state", {})
        if (cached_state.get("mode") in ("Video", "Commercial")
                and cached_state.get("file")
                and age_ms < _GUIDE_HL_STATE_HOLD_MS):
            ridden_state = dict(cached_state)
            ridden_state["seek"] = cached_state.get("seek", 0) + (age_ms / 1000.0)
            return ridden_state
        if age_ms < _GUIDE_HL_STATE_REFRESH_MS:
            return cached_state
    state = calculate_slotted_playback_state(ch_key)
    app_state[cache_key] = {"ch": ch_key, "state": state, "ts": now_ticks}
    return state

