def _get_part_group_key(norm_path):
    if not norm_path:
        return None
    info = _movie_part_info({"path": norm_path})
    if info is None:
        return None
    base, _num = info
    return f"{os.path.dirname(norm_path).lower()}::{base}"


def _get_part_group_gain_cache_entry(group_key):
    if db is None or not group_key:
        return None
    return db.config.get("_part_group_gain_cache", {}).get(group_key)


def _set_part_group_anchor_gain(group_key, norm_path, gain):
    if db is None or not group_key or gain is None:
        return
    cache = db.config.setdefault("_part_group_gain_cache", {})
    cache[group_key] = {"anchor_path": norm_path, "gain": gain, "ts": time.time()}


def _get_cached_media_probe(norm_path):
    if db is None:
        return {}
    return db.config.get("media_probe_cache", {}).get(norm_path, {})


# VALUES CHANGE HERE
_PROBE_CHECKPOINT_MIN_INTERVAL_S = 8.0
_probe_checkpoint_lock = threading.Lock()
_probe_checkpoint_last = 0.0
_probe_checkpoint_timer = None


def _probe_checkpoint_save_now():
    global _probe_checkpoint_last, _probe_checkpoint_timer
    with _probe_checkpoint_lock:
        _probe_checkpoint_last = time.monotonic()
        _probe_checkpoint_timer = None
    try:
        if db is not None:
            db.save_settings_async()
    except Exception as _cp_e:
        log.warning(f"[PROBE CHECKPOINT] save failed (non-fatal): {_cp_e}")


def _checkpoint_probe_cache():
    global _probe_checkpoint_timer
    if db is None:
        return
    with _probe_checkpoint_lock:
        _wait = _PROBE_CHECKPOINT_MIN_INTERVAL_S - (time.monotonic() - _probe_checkpoint_last)
        if _wait > 0:
            if _probe_checkpoint_timer is None:
                _probe_checkpoint_timer = threading.Timer(_wait, _probe_checkpoint_save_now)
                _probe_checkpoint_timer.daemon = True
                _probe_checkpoint_timer.start()
            return
    _probe_checkpoint_save_now()


def _store_cached_media_probe(norm_path, duration=None, gain=None, dims=None):
    if db is None or not norm_path:
        return
    cache = db.config.setdefault("media_probe_cache", {})
    entry = cache.setdefault(norm_path, {})
    _wrote_measurement = False
    _gain_written = False
    if duration and duration > 0:
        entry["duration"] = int(duration)
        entry["duration_source"] = "probed"
        _wrote_measurement = True
    if gain:
        entry["gain"] = gain
        _wrote_measurement = True
        _gain_written = True
    if dims and len(dims) == 2 and dims[0] and dims[1]:
        entry["dims"] = [int(dims[0]), int(dims[1])]
        _wrote_measurement = True
    if _wrote_measurement:
        try:
            _st = os.stat(norm_path)
            entry["measured_at"] = time.time()
            entry["measured_mtime"] = _st.st_mtime
            entry["measured_size"] = _st.st_size
        except OSError:
            pass
    if _gain_written:
        _checkpoint_probe_cache()


def _media_probe_fingerprint_stale(norm_path, entry):
    """True only if the entry's stored fingerprint no longer matches a live stat() of norm_path, i.e. the file was replaced or modified."""
    if not isinstance(entry, dict):
        return False
    _mtime = entry.get("measured_mtime")
    _size = entry.get("measured_size")
    if _mtime is None or _size is None:
        return False
    try:
        _st = os.stat(norm_path)
    except OSError:
        return False
    return _st.st_mtime != _mtime or _st.st_size != _size


# ============================================================================
# SECTION: Orphan pruning for persisted path caches
# ============================================================================

# WARNING: the first tuple's caches are keyed by normpath(...).lower(), the second's by plain normpath(); pruning must match the key case.
_LOWERCASED_KEY_PATH_CACHES = ("media_probe_cache", "caption_cache")
_RAW_KEY_PATH_CACHES = ("dvd_gain_cache",)

# VALUES CHANGE HERE
_ORPHAN_CACHE_PRUNE_INTERVAL_S = 1800


def _prune_orphaned_path_caches():
    """Drop entries from the persisted per-path caches whose file no longer exists on disk."""
    if db is None:
        return {}
    removed_counts = {}
    for cache_name in _LOWERCASED_KEY_PATH_CACHES + _RAW_KEY_PATH_CACHES:
        cache = db.config.get(cache_name)
        if not cache:
            continue
        orphans = [k for k in cache.keys() if not _cached_path_exists(k)]
        for k in orphans:
            cache.pop(k, None)
        if orphans:
            removed_counts[cache_name] = len(orphans)

    _probe_cache = db.config.get("media_probe_cache")
    if _probe_cache:
        _stale_fp = [k for k, v in _probe_cache.items()
                     if _media_probe_fingerprint_stale(k, v)]
        for k in _stale_fp:
            _probe_cache.pop(k, None)
        if _stale_fp:
            removed_counts["media_probe_cache (stale fingerprint)"] = len(_stale_fp)
            log.info(
                "[DURATION PROVENANCE] %d file(s) changed on disk since "
                "their duration/gain/dims were last measured -- cleared "
                "their stale probe cache entr%s so they get re-measured "
                "instead of continuing to use numbers for a file that no "
                "longer exists in that form: %s",
                len(_stale_fp), "y" if len(_stale_fp) == 1 else "ies", _stale_fp[:5],
            )

    if removed_counts:
        total = sum(removed_counts.values())
        log.info(
            "[CACHE PRUNE] removed %d orphaned entr%s for files no longer "
            "on disk: %s", total, "y" if total == 1 else "ies", removed_counts,
        )
        try:
            db.save_settings_async()
        except Exception as e:
            log.warning(f"[CACHE PRUNE] save after prune failed: {e}")
    return removed_counts


def _orphan_cache_prune_loop():
    """Background sweep that periodically runs _prune_orphaned_path_caches()."""
    if _app_shutting_down.wait(_background_scan_pace_seconds(_ORPHAN_CACHE_PRUNE_INTERVAL_S)):
        return
    while True:
        while _background_scan_should_pause():
            if _app_shutting_down.wait(2.0):
                return
        try:
            _prune_orphaned_path_caches()
        except Exception as e:
            log.warning(f"[CACHE PRUNE] sweep iteration failed: {e}")
        if _app_shutting_down.wait(_background_scan_pace_seconds(_ORPHAN_CACHE_PRUNE_INTERVAL_S)):
            return


# ============================================================================
# SECTION: One-time purge of removed scan data
# ============================================================================


def _purge_removed_scan_data():
    """Delete the stored renorm ledger and every per-file gap_scan result left in the saved config."""
    if db is None:
        return
    removed_ledger = 0
    removed_gap = 0
    ledger = db.config.pop("_renorm_sweep_processed", None)
    if ledger is not None:
        removed_ledger = len(ledger) if hasattr(ledger, "__len__") else 1
    cache = db.config.get("media_probe_cache")
    if isinstance(cache, dict):
        for entry in list(cache.values()):
            if isinstance(entry, dict) and entry.pop("gap_scan", None) is not None:
                removed_gap += 1
    if ledger is None and not removed_gap:
        return
    log.info("[CONFIG PURGE] removed old renorm ledger (%d entr%s) and gap_scan data on %d file(s)",
             removed_ledger, "y" if removed_ledger == 1 else "ies", removed_gap)
    try:
        db.save_settings()
    except Exception as e:
        log.warning(f"[CONFIG PURGE] save after purge failed: {e}")


_LOUDNESS_TIMEOUT_BACKOFF_S = (600, 1800, 7200, 21600)


# ============================================================================
# SECTION: Loudness probe cooldowns, probe claims & guarded probes
# ============================================================================


def _loudness_backoff_seconds(streak):
    idx = min(max(streak, 1) - 1, len(_LOUDNESS_TIMEOUT_BACKOFF_S) - 1)
    return _LOUDNESS_TIMEOUT_BACKOFF_S[idx]


def _loudness_probe_in_cooldown(norm_path):
    if db is None or not norm_path:
        return False
    entry = db.config.get("media_probe_cache", {}).get(norm_path, {})
    next_retry = entry.get("loudness_next_retry_ts")
    if not next_retry:
        return False
    _in_cooldown = time.time() < next_retry
    if _in_cooldown:
        _log_warn_throttled(
            f"loudness_cooldown_{norm_path}",
            "[LOUDNESS PROBE] Skipping '%s' -- still in post-timeout cooldown "
            "for %.0fs more (streak %s)",
            os.path.basename(norm_path), next_retry - time.time(),
            entry.get("loudness_timeout_streak", "?"),
            interval=60.0,
        )
    return _in_cooldown


def _record_loudness_timeout(norm_path):
    if db is None or not norm_path:
        return
    cache = db.config.setdefault("media_probe_cache", {})
    entry = cache.setdefault(norm_path, {})
    streak = entry.get("loudness_timeout_streak", 0) + 1
    entry["loudness_timeout_streak"] = streak
    backoff = _loudness_backoff_seconds(streak)
    entry["loudness_next_retry_ts"] = time.time() + backoff
    log.warning(f"[LOUDNESS PROBE] {os.path.basename(norm_path)}: timed out on every "
          f"window (streak {streak}) -- backing off {backoff}s before retrying")


def _clear_loudness_timeout_streak(norm_path):
    if db is None or not norm_path:
        return
    entry = db.config.get("media_probe_cache", {}).get(norm_path)
    if entry and ("loudness_timeout_streak" in entry or "loudness_next_retry_ts" in entry):
        entry.pop("loudness_timeout_streak", None)
        entry.pop("loudness_next_retry_ts", None)


_probe_dispatch_lock = threading.Lock()
_probe_dispatch_inflight = set()


def _probe_marker_path():
    """Path to the tiny standalone "currently probing this" marker file."""
    if db is None:
        return None
    return os.path.join(db.base_dir, "_probe_inflight.json")


def _write_probe_marker(norm_p, field):
    """Records on disk that a probe is about to start, so a crash mid-probe leaves proof of which file and field was in flight."""
    # WARNING: the marker is fsync'd and atomically renamed; a half-written marker must never be possible.
    marker_path = _probe_marker_path()
    if not marker_path:
        return
    try:
        import json as _json
        tmp_path = marker_path + ".tmp"
        with open(tmp_path, "w") as f:
            _json.dump({"path": norm_p, "field": field, "ts": time.time()}, f)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp_path, marker_path)
    except Exception as e:
        log.warning(f"[MEDIA PRECACHE] failed to write probe-in-progress marker: {e}")


def _clear_probe_marker(norm_p, field):
    """Removes the in-flight marker once a probe finishes."""
    marker_path = _probe_marker_path()
    if not marker_path or not os.path.exists(marker_path):
        return
    try:
        import json as _json
        with open(marker_path, "r") as f:
            marker = _json.load(f)
        if marker.get("path") == norm_p and marker.get("field") == field:
            os.remove(marker_path)
    except Exception as e:
        log.warning(f"[MEDIA PRECACHE] failed to clear probe-in-progress marker: {e}")


def _note_probe_started(norm_p, field):
    """Breadcrumb of whatever's actively being probed right now."""
    if db is None:
        return
    db.config["_last_probe_started"] = {"path": norm_p, "field": field, "ts": time.time()}
    _write_probe_marker(norm_p, field)


def _note_probe_finished(norm_p, field):
    if db is None:
        return
    marker = db.config.get("_last_probe_started")
    if marker and marker.get("path") == norm_p and marker.get("field") == field:
        db.config.pop("_last_probe_started", None)
    _clear_probe_marker(norm_p, field)


def _claim_probe(norm_p, field):
    key = (norm_p, field)
    with _probe_dispatch_lock:
        if key in _probe_dispatch_inflight:
            return False
        _probe_dispatch_inflight.add(key)
        _note_probe_started(norm_p, field)
        return True


def _release_probe(norm_p, field):
    with _probe_dispatch_lock:
        _probe_dispatch_inflight.discard((norm_p, field))
        _note_probe_finished(norm_p, field)


def _header_facts(norm_p):
    """The shared header read for one file: {ok, duration, width, height, has_audio}, read once per file by the media library and reused by every lane. None when the library is unavailable."""
    try:
        lib = _get_probe_library()
        return lib.header_facts(norm_p) if lib is not None else None
    except Exception as e:
        _log_warn_throttled("header_facts", "[MEDIA LIBRARY] shared header read unavailable (%s); using separate reads", e)
        return None


media.set_header_facts_provider(_header_facts)


def _probe_duration_guarded(norm_p):
    if not _claim_probe(norm_p, "duration"):
        return None
    try:
        facts = _header_facts(norm_p)
        if facts is not None and facts.get("ok"):
            # WARNING: the library's duration already went through the VLC plausibility fallback; do not open the file in VLC again here.
            return facts.get("duration")
        return get_media_duration(norm_p)
    finally:
        _release_probe(norm_p, "duration")


def _probe_duration_gated(norm_p):
    """Background batch duration probe, admitted by the governor's probe lane."""
    with media._gov_gate("probe_and_duration", label="header_duration(%s)" % os.path.basename(norm_p)):
        return _probe_duration_guarded(norm_p)


def _probe_dims_gated(norm_p):
    """Background batch dimension probe, admitted by the governor's probe lane."""
    with media._gov_gate("probe_and_duration", label="dims(%s)" % os.path.basename(norm_p)):
        return _probe_dims_guarded(norm_p)


def _probe_dims_guarded(norm_p):
    if not _claim_probe(norm_p, "dims"):
        return None
    try:
        return get_media_video_dimensions(norm_p)
    finally:
        _release_probe(norm_p, "dims")


def _governor_nullscope():
    import contextlib as _ctx
    return _ctx.nullcontext()


def _governor_priority_scope():
    """Runs first-scan work (duration, dimensions, loudness of a file about to play) without throttling; a no-op if the governor is missing."""
    if performance_governor is not None:
        return performance_governor.priority_scope()
    import contextlib as _ctx
    return _ctx.nullcontext()


def _probe_duration_and_dims_combined(norm_p):
    """Step 8: boot pre-warm / first-scan header probe -- priority scope around the original."""
    with _governor_priority_scope():
        return _probe_duration_and_dims_combined_impl(norm_p)


def _probe_duration_and_dims_combined_impl(norm_p):
    """One media_library.combined_header_probe() call that returns both duration and dimensions."""
    # WARNING: duration must still go through probe_duration_with_fallback's VLC sanity check.
    facts = _header_facts(norm_p)
    if facts is not None and facts.get("ok"):
        w, h = facts.get("width"), facts.get("height")
        return facts.get("duration"), ((int(w), int(h)) if w and h else None)
    try:
        import media_library as _ml
        result = _ml.combined_header_probe(norm_p)
    except Exception as e:
        log.warning("[MEDIA PRECACHE] combined header probe failed for %s, "
                    "falling back to separate duration/dims probes: %s",
                    os.path.basename(norm_p), e)
        result = None
    if result is None or not result.ok:
        return _probe_duration_seconds_fast(norm_p), _probe_dims_guarded(norm_p)
    try:
        duration, _source = _ml.probe_duration_with_fallback(norm_p, result)
    except Exception as e:
        log.warning("[MEDIA PRECACHE] duration fallback check failed for %s: %s",
                    os.path.basename(norm_p), e)
        duration = result.duration
    dims = (result.width, result.height) if result.width and result.height else None
    return duration, dims


SHOW_SMOOTH_TOLERANCE_DB = 0.3
_show_loudness_floor = {}
_show_loudness_floor_lock = threading.Lock()


def _get_show_smoothing_key(norm_path):
    if not norm_path:
        return None
    parent = os.path.basename(os.path.dirname(norm_path))
    info = _season_folder_base(parent)
    if info:
        return info[1]
    if _bare_season_number(parent) is not None:
        grandparent = os.path.basename(os.path.dirname(os.path.dirname(norm_path)))
        return _normalize_show_key(grandparent) if grandparent else None
    return None


def _apply_show_loudness_smoothing(norm_p, gain, shortfall_info):
    show_key = _get_show_smoothing_key(norm_p)
    if show_key is None or not shortfall_info:
        return gain
    achieved = shortfall_info.get("achieved_lufs")
    measured = shortfall_info.get("measured_lufs")
    peak_capped = shortfall_info.get("peak_capped")
    if achieved is None or measured is None:
        return gain
    with _show_loudness_floor_lock:
        floor = _show_loudness_floor.get(show_key)
        if peak_capped:
            if floor is None or achieved < floor:
                _show_loudness_floor[show_key] = achieved
            return gain
        if floor is not None and achieved > floor + SHOW_SMOOTH_TOLERANCE_DB:
            _smoothed_gain = min(gain, 10 ** ((floor - measured) / 20.0))
            print(f"[LOUDNESS PROBE] *** SHOW SMOOTHED *** {os.path.basename(norm_p)}: "
                  f"would land at {achieved:.1f} LUFS (uncapped) but a peak-limited sibling "
                  f"in this show already established a {floor:.1f} LUFS floor -- "
                  f"matched down to x{_smoothed_gain:.2f} so this episode doesn't stand out "
                  f"louder than its neighbors")
            return _smoothed_gain
    return gain


def _probe_loudness_guarded(norm_p, out_shortfall=None, **kwargs):
    """Governed loudness probe; out_shortfall, if given, receives the raw measurement behind the returned gain."""
    _group_key = _get_part_group_key(norm_p)
    if _group_key:
        _group_entry = _get_part_group_gain_cache_entry(_group_key)
        if _group_entry and os.path.normpath(_group_entry.get("anchor_path", "")) != norm_p:
            print(f"[LOUDNESS PROBE] '{os.path.basename(norm_p)}' is part of the same "
                  f"title as already-scanned '{os.path.basename(_group_entry.get('anchor_path', ''))}' "
                  f"-- reusing its gain x{_group_entry.get('gain', 1.0):.2f} instead of "
                  f"re-measuring this part independently.")
            if out_shortfall is not None:
                out_shortfall["measured_lufs"] = None
            return _group_entry.get("gain", 1.0)

    if not _claim_probe(norm_p, "gain"):
        return None
    try:
        _shortfall_info = {}
        _gain = get_media_loudness_gain(norm_p, shortfall_out=_shortfall_info, db=db, **kwargs)
        if _gain is not None:
            _gain = _apply_show_loudness_smoothing(norm_p, _gain, _shortfall_info)
        if _group_key and _gain is not None:
            _set_part_group_anchor_gain(_group_key, norm_p, _gain)
        if out_shortfall is not None:
            out_shortfall.update(_shortfall_info)
        return _gain
    finally:
        _release_probe(norm_p, "gain")


def _probe_music_loudness_guarded(norm_p, out_shortfall=None, **kwargs):
    """Music counterpart to _probe_loudness_guarded, used only by _music_precache_worker()."""
    if not _claim_probe(norm_p, "gain"):
        return None
    try:
        _shortfall_info = {}
        _gain = get_music_loudness_gain(norm_p, shortfall_out=_shortfall_info, db=db, **kwargs)
        if out_shortfall is not None:
            out_shortfall.update(_shortfall_info)
        return _gain
    finally:
        _release_probe(norm_p, "gain")


UNPLAYABLE_STRIKE_THRESHOLD = 3


# ============================================================================
# SECTION: Probe batches & interrupted-probe recovery
# ============================================================================


def _register_unplayable_strike(norm_path, reason):
    if db is None or not norm_path:
        return 0
    cache = db.config.setdefault("media_probe_cache", {})
    entry = cache.setdefault(norm_path, {})
    count = entry.get("unplayable_strikes", 0) + 1
    entry["unplayable_strikes"] = count
    entry["unplayable_reason"] = reason
    if count >= UNPLAYABLE_STRIKE_THRESHOLD:
        entry["confirmed_unplayable"] = True
    print(f"[PLAYABILITY PROBE] Strike {count}/{UNPLAYABLE_STRIKE_THRESHOLD} for "
          f"'{os.path.basename(norm_path)}' -- {reason}")
    return count


def _mark_confirmed_no_audio(norm_path, reason):
    if db is None or not norm_path:
        return
    cache = db.config.setdefault("media_probe_cache", {})
    entry = cache.setdefault(norm_path, {})
    entry["confirmed_no_audio"] = True
    entry["no_audio_reason"] = reason
    print(f"[PLAYABILITY PROBE] Confirmed no audible content in "
          f"'{os.path.basename(norm_path)}' -- {reason}")


def _seed_probe_cache_from_schedules():
    if db is None:
        return 0
    try:
        cache = db.config.setdefault("media_probe_cache", {})
    except Exception:
        return 0
    channels = getattr(db, "channels_db", None)
    if not isinstance(channels, dict):
        return 0
    seeded = 0
    for _ch_id, ch_info in list(channels.items()):
        if not isinstance(ch_info, dict):
            continue
        schedules = ch_info.get("schedules", {})
        if not isinstance(schedules, dict):
            continue
        for _block_name, entries in list(schedules.items()):
            if not isinstance(entries, list):
                continue
            for entry in entries:
                if not isinstance(entry, dict):
                    continue
                path = entry.get("path")
                if not path:
                    continue
                dur = entry.get("duration")
                gain = entry.get("gain")
                has_real_dur = isinstance(dur, (int, float)) and not isinstance(dur, bool) and dur > 0
                has_gain = isinstance(gain, (int, float)) and not isinstance(gain, bool)
                if not (has_real_dur or has_gain):
                    continue
                try:
                    norm = os.path.normpath(str(path))
                except Exception:
                    continue
                existing = cache.get(norm)
                if not isinstance(existing, dict):
                    existing = {}
                    cache[norm] = existing
                if has_real_dur and not existing.get("duration"):
                    existing["duration"] = int(dur)
                    seeded += 1
                if has_gain and existing.get("gain") is None:
                    existing["gain"] = gain
    return seeded


def _register_probe_batch(batch_id, ch_key, container_key, sub_key, remaining_paths):
    """Records a batch probe pass so it can be resumed if the app goes down mid-pass."""
    if db is None:
        return
    batches = db.config.setdefault("_active_probe_batches", {})
    batches[batch_id] = {
        "ch": ch_key,
        "container": container_key,
        "sub": sub_key,
        "remaining": list(remaining_paths),
        "ts": time.time(),
    }


def _update_probe_batch_progress(batch_id, remaining_paths):
    if db is None:
        return
    batches = db.config.get("_active_probe_batches")
    if batches is not None and batch_id in batches:
        batches[batch_id]["remaining"] = list(remaining_paths)
        batches[batch_id]["ts"] = time.time()


def _clear_probe_batch(batch_id):
    if db is None:
        return
    batches = db.config.get("_active_probe_batches")
    if batches is not None:
        batches.pop(batch_id, None)


def _report_interrupted_probe_marker():
    """Startup check: finds the file and field that were in flight when the last run died mid-probe."""
    # WARNING: whatever is cached for that file and field is untrusted, even if a value already reached the cache.
    if db is None:
        return
    db.config.pop("_last_probe_started", None)

    marker_path = _probe_marker_path()
    if not marker_path or not os.path.exists(marker_path):
        return

    try:
        import json as _json
        with open(marker_path, "r") as f:
            marker = _json.load(f)
    except Exception as e:
        log.warning(f"[MEDIA PRECACHE] could not read leftover probe marker "
                    f"(removing it): {e}")
        try:
            os.remove(marker_path)
        except Exception:
            pass
        return

    path = marker.get("path")
    field = marker.get("field")

    try:
        os.remove(marker_path)
    except Exception:
        pass

    if not path or not field:
        return

    norm_p = os.path.normpath(path)
    cache = db.config.setdefault("media_probe_cache", {})
    entry = cache.get(norm_p)
    had_cached_value = bool(entry and field in entry)
    if entry and field in entry:
        entry.pop(field, None)

    log.warning(
        f"[MEDIA PRECACHE] Last run was interrupted mid-probe on "
        f"'{os.path.basename(path)}' ({field})" +
        (" -- had a cached value already, but clearing it since a probe "
         "that got cut off mid-parse can't be trusted; queuing a clean "
         "re-probe." if had_cached_value else
         " -- no cached value yet; queuing a probe.")
    )

    def _requeue():
        try:
            if field == "duration":
                _probe_duration_guarded(norm_p)
            elif field == "dims":
                _probe_dims_guarded(norm_p)
            elif field == "gain":
                if _is_drive_degraded(norm_p):
                    log.warning("[MEDIA PRECACHE] not re-probing gain for %s right now -- "
                                "its drive looks degraded (%s)",
                                os.path.basename(norm_p), _drive_latency_summary(norm_p))
                else:
                    _probe_loudness_guarded(norm_p)
        except Exception as e:
            log.warning(f"[MEDIA PRECACHE] re-probe of interrupted file "
                        f"'{os.path.basename(norm_p)}' ({field}) failed: {e}")

    threading.Thread(target=_requeue, daemon=True).start()


def _resume_interrupted_probe_batches():
    """Startup check: resumes batch probe passes that were still in progress when the app last went down."""
    if db is None:
        return
    batches = db.config.get("_active_probe_batches", {})
    if not batches:
        return
    for batch_id, info in list(batches.items()):
        remaining = info.get("remaining") or []
        if not remaining:
            _clear_probe_batch(batch_id)
            continue
        
        threading.Thread(
            target=_probe_and_patch_durations,
            args=(info.get("ch"), info.get("container"), info.get("sub"), remaining),
            kwargs={"_resume_batch_id": batch_id},
            daemon=True,
        ).start()


