# SECTION: Channel schedule membership
# ============================================================================

# VALUES CHANGE HERE
_SCHED_MEMBERSHIP_CACHE_SECONDS = 5.0


def _channel_schedule_path_set(ch_key):
    """Returns the normalized paths in ch_key's own schedule and holiday lists (pair episodes included), cached briefly."""
    ch_info = db.channels_db.get(str(ch_key).zfill(2), {}) if db is not None else {}
    cache = app_state.setdefault("_sched_membership_cache", {})
    pools = list((ch_info.get("schedules") or {}).values())
    for _hol in (ch_info.get("holiday_schedules") or {}).values():
        pools.append(_hol)
    signature = (len(pools), sum(len(p) for p in pools if isinstance(p, list)))
    hit = cache.get(str(ch_key))
    now = time.monotonic()
    if hit is not None and hit[0] == signature and now - hit[1] < _SCHED_MEMBERSHIP_CACHE_SECONDS:
        return hit[2]
    paths = set()
    for pool in pools:
        if not isinstance(pool, list):
            continue
        for entry in pool:
            if isinstance(entry, dict):
                candidates = [entry.get("path", entry.get("file", ""))]
                candidates += [v for k, v in entry.items()
                               if isinstance(k, str) and k.startswith("pair_ep") and k.endswith("_path")]
            else:
                candidates = [entry]
            for cand in candidates:
                if cand:
                    paths.add(os.path.normcase(os.path.normpath(str(cand))))
    cache[str(ch_key)] = (signature, now, paths)
    return paths


def _file_in_channel_schedule(ch_key, path):
    """True if `path` is in ch_key's own schedule or holiday lists; also True when the channel has no lists or the check fails."""
    if not path:
        return False
    try:
        paths = _channel_schedule_path_set(ch_key)
        if not paths:
            return True
        return os.path.normcase(os.path.normpath(str(path))) in paths
    except Exception as _membership_err:
        log.warning("_file_in_channel_schedule: check failed for ch%s: %s", ch_key, _membership_err)
        return True


