# SECTION: Volume & gain helpers
# ============================================================================


def _perceptual_volume_pct(slider_pct, min_db=-40.0):
    pct = max(0, min(100, slider_pct))
    if pct <= 0:
        return 0.0
    frac = pct / 100.0
    db_level = min_db * (1.0 - frac)
    amplitude_frac = 10 ** (db_level / 20.0)
    return amplitude_frac * 100.0


STACKED_GAIN_MIN_DB = -48.0


VLC_GAIN_MIN_DB = -18.0


VLC_VOLUME_CEILING = int(100 * LOUDNESS_GAIN_CEILING)

# VALUES CHANGE HERE
MAX_COMFORTABLE_VOLUME = 135


def _effective_audio_gain(min_db=-40.0):
    if db is not None and db.config.get("is_muted", False):
        return 0.0
    vol = db.config.get("global_volume", 70) if db is not None else 70
    return _perceptual_volume_pct(vol, min_db=min_db) / 100.0


def _effective_loudness_gain(gain):
    """Returns a probed media gain only while Loudness Scan is enabled."""
    # WARNING: pygame-backed audio needs this gate explicitly, or turning Loudness Scan off leaves a loaded track at its stored multiplier.
    if db is None or not db.config.get("loudness_scan_enabled", True):
        return 1.0
    try:
        return float(gain) if gain and float(gain) > 0 else 1.0
    except (TypeError, ValueError):
        return 1.0


_STATIC_AUDIO_GAIN_PRECACHED = 0.25

_STATIC_AUDIO_GAIN = _STATIC_AUDIO_GAIN_PRECACHED


# ============================================================================
# SECTION: Transition static & mute guard
# ============================================================================


def load_custom_static_sound():
    global _STATIC_AUDIO_GAIN
    w_path = resource_path(os.path.join("main", "audio", "static.wav"))

    if os.path.exists(w_path):
        try:
            s = pygame.mixer.Sound(w_path)
            s.set_volume(_effective_audio_gain() * _effective_loudness_gain(_STATIC_AUDIO_GAIN))
            return s
        except Exception as e:
            log.warning("load_custom_static_sound: failed to load %s, falling back to generated noise: %s", w_path, e)

    try:
        _mixer_freq, _mixer_fmt, _mixer_ch = pygame.mixer.get_init()
    except Exception:
        _mixer_freq, _mixer_ch = 44100, 2
    _mixer_ch = _mixer_ch if _mixer_ch in (1, 2) else 2
    _duration_s = 1.0
    _n_frames = int(_mixer_freq * _duration_s)
    _amplitude = 3000
    _samples = array.array('h')
    for _ in range(_n_frames):
        _val = random.randint(-_amplitude, _amplitude)
        _samples.append(_val)
        if _mixer_ch == 2:
            _samples.append(_val)
    s = pygame.mixer.Sound(buffer=_samples.tobytes())
    _STATIC_AUDIO_GAIN = _STATIC_AUDIO_GAIN_PRECACHED
    s.set_volume(_effective_audio_gain() * _effective_loudness_gain(_STATIC_AUDIO_GAIN))
    return s

static_audio = load_custom_static_sound()
print("[TELEMETRY - PART 4] Static audio noise generator loaded.")


def _aspect_fit_rect(rect, target_aspect=None):
    """Centered sub-rect of `rect` at `target_aspect` (width/height); None returns `rect` unchanged."""
    if target_aspect is None:
        return rect
    rw, rh = rect.width, rect.height
    if rw <= 0 or rh <= 0 or target_aspect <= 0:
        return rect
    if (rw / rh) > target_aspect:
        dh = rh
        dw = max(1, round(dh * target_aspect))
    else:
        dw = rw
        dh = max(1, round(dw / target_aspect))
    dx = rect.x + (rw - dw) // 2
    dy = rect.y + (rh - dh) // 2
    return pygame.Rect(dx, dy, dw, dh)


_transition_static_noise_cache = {"key": None, "surface": None, "built_at": 0}


def _render_transition_static(screen, rect, target_aspect=None):
    """Renders the transition static burst inside `rect`; target_aspect overrides the global Aspect Ratio setting."""
    # WARNING: the guide preview box is a fixed 16:9 rect; only the video inside it is pillarboxed to 4:3, never the box.
    if 'static_audio' in globals() and static_audio is not None and static_audio.get_num_channels() == 0:
        static_audio.play(-1)
        static_audio.set_volume(_effective_audio_gain() * _effective_loudness_gain(_STATIC_AUDIO_GAIN))

    fit_rect = _aspect_fit_rect(rect, target_aspect=target_aspect)
    if fit_rect.width < rect.width or fit_rect.height < rect.height:
        screen.fill(_video_bar_color(), rect)
    rect = fit_rect

    sw, sh = rect.width // 4, rect.height // 4
    if sw > 0 and sh > 0:
        noise_style = db.config.get("static_noise_color", "white") if db is not None else "white"
        theme_hue = db.config.get("theme_bg_hue", 220) if (db is not None and noise_style == "theme") else 0

        now = pygame.time.get_ticks()
        key = (rect.width, rect.height, noise_style, theme_hue)
        cache = _transition_static_noise_cache
        if (cache["key"] != key or cache["surface"] is None
                or now - cache["built_at"] >= _STATIC_NOISE_REFRESH_MS):
            if noise_style == "rainbow":
                noise = np.random.randint(30, 170, (sw, sh, 3), dtype=np.uint8)
            elif noise_style == "theme":
                import colorsys as _theme_static_colorsys
                _bg_hue = theme_hue / 360.0
                _tr, _tg, _tb = _theme_static_colorsys.hsv_to_rgb(_bg_hue, 0.9, 1.0)
                theme_rgb = np.array([_tr, _tg, _tb], dtype=np.float32)
                intensity = np.random.randint(20, 86, (sw, sh, 1)).astype(np.float32)
                noise = (intensity * theme_rgb.reshape(1, 1, 3)).astype(np.uint8)
            elif noise_style == "white":
                white = np.random.randint(100, 155, (sw, sh, 1), dtype=np.uint8)
                noise = np.repeat(white, 3, axis=2)
            else:
                gray = np.random.randint(10, 55, (sw, sh, 1), dtype=np.uint8)
                noise = np.repeat(gray, 3, axis=2)
            surf = pygame.surfarray.make_surface(noise)
            cache["surface"] = pygame.transform.scale(surf, (rect.width, rect.height))
            cache["key"] = key
            cache["built_at"] = now
        screen.blit(cache["surface"], (rect.x, rect.y))
    else:
        screen.fill((1, 1, 1), rect)


def _stop_transition_static():
    if 'static_audio' in globals() and static_audio is not None:
        static_audio.stop()


def _mute_guard_engine(ch):
    """Which VLCEngineWrapper the mute guard should actually be watching/muting for the given channel."""
    if str(ch).zfill(2) == "03" and game_deck is not None and getattr(game_deck, "dvd_playback_active", False):
        return dvd_engine
    return vlc_engine


def _mute_guard_log(event, ch=None, filepath=None, extra=""):
    _engine = _mute_guard_engine(ch)
    _tid = threading.get_ident()
    _short_fp = os.path.basename(filepath) if filepath else None
    _cur_fp = os.path.basename(getattr(_engine, "current_filepath", "") or "") if _engine is not None else "?"
    try:
        _mute_now = _engine.player.audio_get_mute() if _engine is not None else "?"
    except Exception:
        _mute_now = "?"
    print(f"[MUTE GUARD] {event} | thread={_tid} ch={ch} armed_for={_short_fp} "
          f"engine_current_file={_cur_fp} pending_unmute={app_state.get('_video_pending_unmute', False)} "
          f"audio_get_mute()={_mute_now} {extra}")


_mute_guard_lock = threading.Lock()
_mute_guard_generation = 0


def _arm_mute_guard_watchdog(ch, filepath):
    """Single spawn point for the buffering mute-guard watchdog."""
    global _mute_guard_generation
    with _mute_guard_lock:
        _mute_guard_generation += 1
        _generation = _mute_guard_generation
    threading.Thread(target=_watchdog_hold_mute_during_buffering,
                      args=(ch, filepath, _generation), daemon=True).start()
    return _generation


def _watchdog_hold_mute_during_buffering(ch, filepath=None, generation=None):
    _engine = _mute_guard_engine(ch)
    if _engine is None:
        return
    _mute_guard_log("watchdog SPAWNED", ch=ch, filepath=filepath)
    _deadline = time.time() + 5.0
    _landed_logged = False
    while time.time() < _deadline:
        _engine = _mute_guard_engine(ch)
        if _engine is None:
            return
        if filepath is not None and getattr(_engine, "current_filepath", None) != filepath:
            _mute_guard_log("watchdog BAIL (superseded)", ch=ch, filepath=filepath)
            return
        if generation is not None and generation != _mute_guard_generation:
            _mute_guard_log("watchdog BAIL (superseded, stale generation)", ch=ch, filepath=filepath)
            return
        if not app_state.get("_video_pending_unmute", False):
            _mute_guard_log("watchdog BAIL (flag cleared)", ch=ch, filepath=filepath)
            return
        try:
            _cur = _engine.player.audio_get_mute()
            if _cur != 1:
                _mute_guard_log("watchdog FORCE-REMUTE", ch=ch, filepath=filepath,
                                 extra=f"(saw audio_get_mute()={_cur}, forcing back to muted)")
                _engine.player.audio_set_mute(True)
            elif not _landed_logged:
                
                _landed_logged = True
        except Exception:
            return
        time.sleep(0.1)
    _mute_guard_log("watchdog TIMED OUT (5s)", ch=ch, filepath=filepath)


def _lift_buffering_mute(ch, reason):
    if not app_state.get("_video_pending_unmute", False):
        return
    app_state["_video_pending_unmute"] = False
    _mute_guard_log("lift CLEARING flag", ch=ch, extra=f"reason={reason}")
    _still_muted = db.config.get("is_muted", False) if db is not None else False

    _engine = _mute_guard_engine(ch)
    if _engine is None:
        return
    if not _still_muted:
        try: _engine.player.audio_set_mute(False)
        except Exception: pass
    else:
        try: _engine.player.audio_set_mute(True)
        except Exception: pass

    try:
        _post_lift_mute = _engine.player.audio_get_mute()
    except Exception:
        _post_lift_mute = "?"
    if _post_lift_mute == -1:
        def _verify_mute_landed(_ch=ch, _reason=reason, _want_muted=_still_muted, _engine=_engine):
            _deadline = time.time() + 5.0
            _tries = 0
            while time.time() < _deadline:
                time.sleep(0.2)
                _tries += 1
                try:
                    if _engine is None:
                        return
                    _cur = _engine.player.audio_get_mute()
                except Exception:
                    return
                if _cur != -1:
                    
                    return
                try:
                    _engine.player.audio_set_mute(_want_muted)
                    if db is not None:
                        _engine.set_volume(
                            db.config.get("global_volume", 70),
                            db.config.get("is_muted", False),
                        )
                except Exception:
                    return
            
        threading.Thread(target=_verify_mute_landed, daemon=True).start()


def _note_fresh_live_video_frame(ch):
    """Bookkeeping for a newly decoded live-TV frame, run by the render pass that consumes it."""
    app_state["_last_new_frame_ticks"] = pygame.time.get_ticks()
    app_state["_had_first_frame_this_tune"] = True
    if pygame.time.get_ticks() >= app_state.get("channel_switch_black_until", 0):
        _stop_transition_static()
        _lift_buffering_mute(ch, "first-frame")
        app_state["_video_audio_hold_until"] = 0
    app_state["_boot_suppress_static"] = False


