def _run_pending_channel_activation():
    _fn = app_state.pop("_pending_channel_activation", None)
    if _fn is not None:
        try:
            _fn()
        except Exception as e:
            log.warning("[ACTIVATION] pending channel activation failed: %s", e)


_channel_activation_lock = threading.Lock()
_channel_activation_generation = 0


def _dispatch_content_activation(fn):
    global _channel_activation_generation
    _channel_activation_generation += 1
    my_generation = _channel_activation_generation

    def _run():
        with _channel_activation_lock:
            if my_generation != _channel_activation_generation:
                return
            set_live_playback_priority(True)
            try:
                fn()
            except Exception as e:
                log.warning("[ACTIVATION] channel content activation failed: %s", e)
            finally:
                set_live_playback_priority(False)

    threading.Thread(target=_run, daemon=True, name="content-activate").start()


_ch03_audio_lock = threading.Lock()
_ch03_audio_generation = 0

# WARNING: setting this to False causes a visible reload/re-buffer on every real tune-in.
_GUIDE_WARM_CONTINUATION_ENABLED = True


def change_channel(new_ch, is_surfing=False, force_reload=False, internal_advance=False, is_boot=False, pre_captured_position=None, snap_internal_advance=None):
    if (app_state.get("current_channel") == new_ch and app_state.get("is_playing_video", False)
            and not force_reload):
        return

    if not pygame.display.get_surface():
        print("[HARDWARE SHIELD] Refusing channel switch pass: Surface layout is uninitialized.")
        return

    _mid_static_burst = pygame.time.get_ticks() < app_state.get("channel_switch_black_until", 0)
    if (not _mid_static_burst and not internal_advance
            and 'static_audio' in globals() and static_audio is not None):
        static_audio.stop()
    
    old_ch = app_state.get("current_channel", "05")

    _outgoing_live_snapshot = None
    if old_ch not in ("03", "04") and vlc_engine is not None:
        try:
            _outgoing_state = vlc_engine.player.get_state()
            _outgoing_pos = vlc_engine.player.get_time()
            _outgoing_media = vlc_engine.player.get_media()
            _outgoing_mrl = _outgoing_media.get_mrl() if _outgoing_media else ""
            if (_outgoing_mrl and _outgoing_pos is not None and _outgoing_pos >= 0
                    and _outgoing_state not in (vlc.State.Ended, vlc.State.Error)):
                from urllib.parse import unquote as _unquote_outgoing
                _outgoing_file = os.path.normpath(
                    _unquote_outgoing(_outgoing_mrl.replace("file:///", "")))
                _outgoing_live_snapshot = {
                    "file": _outgoing_file,
                    "pos": _outgoing_pos / 1000.0,
                    "duration": max(1, (vlc_engine.player.get_length() or 0) / 1000.0),
                    "mode": (
                        "Commercial"
                        if _is_commercial_file_for_channel(old_ch, _outgoing_file)
                        else "Video"
                    ),
                }
        except Exception as _outgoing_snapshot_err:
            log.debug("change_channel: outgoing VLC snapshot unavailable: %s",
                      _outgoing_snapshot_err)

    if old_ch == "04" and new_ch != "04":
        global _last_screen_mode_picture_rect
        _last_screen_mode_picture_rect = None

    if old_ch == "03" and new_ch != "03":
        _stop_ch03_menu_music()
        if game_deck is not None and game_deck.is_process_running():
            _lr = getattr(game_deck, "_libretro_core", None)
            if _lr is not None and _lr.is_loaded:
                game_deck.set_paused(True, hard=True, reason="channel")
            else:
                import threading as _t
                _t.Thread(
                    target=lambda: (
                        game_deck.set_viewport_state(visible=False),
                        game_deck.set_audio_state(muted=True)
                    ),
                    daemon=True
                ).start()
        if (game_deck is not None and game_deck.dvd_playback_active
                and dvd_engine is not None):
            try:
                dvd_engine.player.audio_set_mute(True)
                game_deck.dvd_iso_backgrounded = True
                print("[DVD] Backgrounded on channel leave -- dvd_engine muted, "
                      "left running as-is (unmute-in-place on return, no reopen).")
            except Exception as _me:
                log.warning(f"[DVD] Failed to mute backgrounded DVD on channel leave: {_me}")
    
    app_state["current_channel"] = new_ch
    app_state["_live_playback_channel"] = ""

    if db is not None and new_ch not in ("03", "04"):
        db.config["last_channel"] = new_ch
        _now_ms = pygame.time.get_ticks()
        if _now_ms - app_state.get("_last_channel_save_ms", -10_000) >= 1000:
            app_state["_last_channel_save_ms"] = _now_ms
            try:
                db.save_settings_async()
            except Exception as _lc_err:
                log.warning(f"[PERSIST] last_channel async save failed: {_lc_err}")

    _ch03_activate = None
    if new_ch == "03":
        if game_deck is not None:
            _muted = db.config.get("is_muted", False) if db else False
            _active_con = getattr(game_deck, "active_console", None) or getattr(game_deck, "_libretro_console", None)
            if _active_con and db and hasattr(game_deck, "sync_profile_from_db"):
                game_deck.sync_profile_from_db(_active_con, db.config)
            _wants_menu_music = (
                getattr(game_deck, "mode", "BROWSE") in ("BROWSE", "ROMLIST")
                and not getattr(game_deck, "dvd_playback_active", False)
            )
            _lr = getattr(game_deck, "_libretro_core", None)
            if _lr is not None and _lr.is_loaded:
                def _ch03_activate(_muted=_muted, _wants_menu_music=_wants_menu_music):
                    _burst_active = (
                        _transition_style_now == "static"
                        and pygame.time.get_ticks() < app_state.get("channel_switch_black_until", 0)
                    )
                    _effective_muted = _muted or _burst_active
                    game_deck.set_paused(False, reason="channel", muted=_effective_muted)
                    game_deck.set_libretro_volume(db.config.get("global_volume", 70) if db else 70, _effective_muted)
                    if _burst_active:
                        app_state["_ch03_static_mute_active"] = True
                    if _wants_menu_music:
                        _start_ch03_menu_music()
            elif game_deck.is_process_running():
                def _ch03_activate(_muted=_muted, _wants_menu_music=_wants_menu_music):
                    _burst_active = (
                        _transition_style_now == "static"
                        and pygame.time.get_ticks() < app_state.get("channel_switch_black_until", 0)
                    )
                    _effective_muted = _muted or _burst_active
                    if _burst_active:
                        app_state["_ch03_static_mute_active"] = True
                    _mute_retry_ms = None
                    if _burst_active:
                        _remaining = app_state.get("channel_switch_black_until", 0) - pygame.time.get_ticks()
                        _mute_retry_ms = max(0, _remaining - 150)
                    global _ch03_audio_generation
                    _ch03_audio_generation += 1
                    _my_ch03_audio_generation = _ch03_audio_generation
                    import threading as _t
                    def _do_activate():
                        with _ch03_audio_lock:
                            if _my_ch03_audio_generation != _ch03_audio_generation:
                                return
                            game_deck.set_audio_state(muted=_effective_muted, retry_deadline_ms=_mute_retry_ms)
                            game_deck.set_viewport_state(visible=True)
                    _t.Thread(target=_do_activate, daemon=True).start()
                    if _wants_menu_music:
                        _start_ch03_menu_music()
            else:
                game_deck.pre_boot_background_deck(parent_hwnd=pygame_hwnd)
                if _wants_menu_music:
                    def _ch03_activate(_wants_menu_music=_wants_menu_music):
                        _start_ch03_menu_music()
        
    # WARNING: capture the current playing track before running any calculation updates.
    current_playing_track = app_state.get("active_music_track_file", "")
    

    _old_snap_key = str(old_ch).zfill(2)

    _snap_vlc_live = False
    if pre_captured_position is not None and pre_captured_position.get("file") \
            and pre_captured_position.get("pos_ms") is not None and pre_captured_position.get("pos_ms") >= 0:
        _snap_vlc_live = True
    elif vlc is not None and vlc_engine is not None:
        try:
            _sv = vlc_engine.player.get_state()
            _snap_vlc_live = _sv not in (vlc.State.Stopped, vlc.State.Ended,
                                          vlc.State.Error, vlc.State.NothingSpecial)
        except Exception:
            pass
    else:
        _snap_vlc_live = False

    

    _fresh_self_anchor = False

    if (old_ch not in ("03", "04") and vlc_engine is not None
            and app_state.get("is_playing_video", False) and db is not None
            and _snap_vlc_live):
        try:
            if pre_captured_position is not None:
                _pos_ms = pre_captured_position.get("pos_ms")
                _dur_ms = pre_captured_position.get("dur_ms")
            else:
                _pos_ms  = vlc_engine.player.get_time()
                _dur_ms  = vlc_engine.player.get_length()
            _old_ch_entry = db.channels_db.setdefault(_old_snap_key, {})
            _old_anc = _old_ch_entry.get("playback_anchor") or {}
            if _pos_ms is not None and _pos_ms >= 0:
                _live_file = None
                if pre_captured_position is not None and pre_captured_position.get("file"):
                    _live_file = pre_captured_position["file"]
                else:
                    try:
                        _media = vlc_engine.player.get_media()
                        if _media:
                            from urllib.parse import unquote as _unquote2
                            _mrl = _media.get_mrl()
                            if _mrl:
                                _live_file = os.path.normpath(_unquote2(_mrl.replace("file:///", "")))
                    except Exception as _mrl_err:
                        log.warning("change_channel: could not read live MRL for leave-anchor on ch%s: %s", _old_snap_key, _mrl_err)

                if not _old_anc.get("file") and _live_file and _file_in_channel_schedule(_old_snap_key, _live_file):
                    _old_anc = {
                        "file": _live_file,
                        "mode": (
                            "Commercial"
                            if _is_commercial_file_for_channel(_old_snap_key, _live_file)
                            else "Video"
                        ),
                        "block": _old_anc.get("block", "Morning"),
                        "duration": max(1800, int(_dur_ms // 1000)) if _dur_ms and _dur_ms > 0 else 1800,
                        "slot_start_seek": 0,
                    }

                if _old_anc.get("file"):
                    _old_anc["wall_start"]  = broadcast_clock.seconds_since_midnight()
                    _old_anc["seek_offset"] = _pos_ms / 1000.0
                    if _dur_ms and _dur_ms > 0:
                        _old_anc["duration"] = max(_old_anc.get("duration", 1800), int(_dur_ms // 1000))
                    _old_anc["anchor_written_at"] = broadcast_clock.now().timestamp()
                    _old_ch_entry["playback_anchor"] = _old_anc
                    print(f"[ANCHOR] Snapped ch{_old_snap_key} leave-position to {_old_anc['seek_offset']:.3f}s.")
                    if str(new_ch).zfill(2) == _old_snap_key:
                        _fresh_self_anchor = True
                    
                else:
                    pass
            else:
                pass
        except Exception as e:
            log.warning("change_channel: failed to snap leave-position anchor for ch%s: %s", _old_snap_key, e)

    _guide_entry_warm_skip_stop = False
    _guide_entry_warm_target_file = None
    if (_GUIDE_WARM_CONTINUATION_ENABLED and new_ch == "04" and old_ch and old_ch != "04"
            and vlc_engine is not None):
        _warm_hl = str(app_state.get("highlighted_guide_channel", "05")).zfill(2)
        try:
            if int(_warm_hl) < 5:
                _warm_hl = "05"
        except (ValueError, TypeError):
            _warm_hl = "05"
        if (_outgoing_live_snapshot is not None
                and _warm_hl == str(old_ch).zfill(2)):
            _warm_guide_target = {
                "mode": _outgoing_live_snapshot.get("mode", "Video"),
                "file": _outgoing_live_snapshot["file"],
                "seek": _outgoing_live_snapshot["pos"],
                "duration": _outgoing_live_snapshot["duration"],
            }
        else:
            try:
                _warm_guide_target = calculate_slotted_playback_state(_warm_hl)
            except Exception:
                _warm_guide_target = {}
        _warm_loaded_norm = os.path.normpath(
            str(getattr(vlc_engine, "current_filepath", "") or "")).lower()
        _warm_target_norm = os.path.normpath(
            str(_warm_guide_target.get("file") or "")).lower()
        if (_warm_guide_target.get("mode") in ("Video", "Commercial")
                and _warm_guide_target.get("file")
                and _warm_loaded_norm
                and _warm_loaded_norm == _warm_target_norm):
            try:
                _guide_entry_warm_skip_stop = vlc_engine.player.is_playing()
            except Exception:
                _guide_entry_warm_skip_stop = False
            if _guide_entry_warm_skip_stop:
                _guide_entry_warm_target_file = _warm_guide_target["file"]

    _guide_entry_warm_skip_music_stop = False
    _guide_entry_warm_music_file = None
    if (_GUIDE_WARM_CONTINUATION_ENABLED and new_ch == "04" and old_ch and old_ch != "04"
            and app_state.get("music_owner") == "live_visualizer"):
        _warm_hl_vis = str(app_state.get("highlighted_guide_channel", "05")).zfill(2)
        try:
            if int(_warm_hl_vis) < 5:
                _warm_hl_vis = "05"
        except (ValueError, TypeError):
            _warm_hl_vis = "05"
        if _warm_hl_vis == str(old_ch).zfill(2):
            try:
                _warm_guide_vis_target = calculate_slotted_playback_state(_warm_hl_vis)
            except Exception:
                _warm_guide_vis_target = {}
            _warm_vis_loaded_norm = os.path.normpath(str(current_playing_track or "")).lower()
            _warm_vis_target_norm = os.path.normpath(
                str(_warm_guide_vis_target.get("file") or "")).lower()
            if (_warm_guide_vis_target.get("mode") == "Visualizer"
                    and _warm_guide_vis_target.get("file")
                    and _warm_vis_loaded_norm
                    and _warm_vis_loaded_norm == _warm_vis_target_norm
                    and pygame.mixer.music.get_busy()):
                _guide_entry_warm_skip_music_stop = True
                _guide_entry_warm_music_file = current_playing_track

    _guide_exit_warm_skip_stop = False
    if _GUIDE_WARM_CONTINUATION_ENABLED and old_ch == "04" and new_ch != "04" and vlc_engine is not None:
        try:
            _exit_warm_target = calculate_slotted_playback_state(new_ch)
        except Exception:
            _exit_warm_target = {}
        _exit_loaded_norm = os.path.normpath(
            str(getattr(vlc_engine, "current_filepath", "") or "")).lower()
        _exit_target_norm = os.path.normpath(
            str(_exit_warm_target.get("file") or "")).lower()
        if (_exit_warm_target.get("mode") in ("Video", "Commercial")
                and _exit_warm_target.get("file")
                and _exit_loaded_norm
                and _exit_loaded_norm == _exit_target_norm):
            try:
                _guide_exit_warm_skip_stop = vlc_engine.player.is_playing()
            except Exception:
                _guide_exit_warm_skip_stop = False
            if _guide_exit_warm_skip_stop:
                _seed_last_video_frame("fullscreen", "preview")
                _warm_transition_style = db.config.get("transition_type", "black") if db is not None else "black"
                _warm_burst_ms = STATIC_TRANSITION_MS if _warm_transition_style == "static" else GUIDE_PREVIEW_SETTLE_MS
                app_state["channel_switch_black_until"] = pygame.time.get_ticks() + _warm_burst_ms
                # WARNING: the shield's own timer owns unmuting here, not the readiness lifter.
                app_state["_video_pending_unmute"] = False
                _arm_warm_transition_shield(vlc_engine, _warm_burst_ms)
                _mute_guard_log("ARM (guide-exit warm transition shield)", ch=new_ch)

    _guide_exit_warm_skip_music_stop = False
    if _GUIDE_WARM_CONTINUATION_ENABLED and old_ch == "04" and new_ch != "04":
        _exit_guide_preview_track = app_state.get("guide_preview_music_track", "")
        if app_state.get("music_owner") == "guide_preview" and _exit_guide_preview_track:
            try:
                _exit_warm_vis_target = calculate_slotted_playback_state(new_ch)
            except Exception:
                _exit_warm_vis_target = {}
            _exit_vis_loaded_norm = os.path.normpath(str(_exit_guide_preview_track or "")).lower()
            _exit_vis_target_norm = os.path.normpath(
                str(_exit_warm_vis_target.get("file") or "")).lower()
            if (_exit_warm_vis_target.get("mode") == "Visualizer"
                    and _exit_warm_vis_target.get("file")
                    and _exit_vis_loaded_norm
                    and _exit_vis_loaded_norm == _exit_vis_target_norm
                    and pygame.mixer.music.get_busy()):
                _guide_exit_warm_skip_music_stop = True

    _warm_continue_skip_stop = _guide_entry_warm_skip_stop or _guide_exit_warm_skip_stop
    _warm_continue_skip_music_stop = (
        _guide_entry_warm_skip_music_stop or _guide_exit_warm_skip_music_stop)

    if vlc_engine is not None and not _warm_continue_skip_stop:
        try:
            vlc_engine.player.audio_set_mute(True)
        except Exception as e:
            log.warning(f"[CHANNEL] pre-stop mute failed: {e}")
        try:
            vlc_engine.stop(block=False)
        except Exception as e:
            log.warning(f"[CHANNEL] immediate outgoing vlc stop failed: {e}")
    if not _warm_continue_skip_music_stop:
        if pygame.mixer.music.get_busy():
            pygame.mixer.music.stop()
        app_state["music_owner"] = ""
        app_state["guide_preview_music_track"] = ""
    elif _guide_entry_warm_skip_music_stop:
        app_state["music_owner"] = "guide_preview"
        app_state["guide_preview_music_track"] = _guide_entry_warm_music_file

    if not internal_advance and not _warm_continue_skip_stop:
        _clear_last_video_frame(context="fullscreen")

    _transition_style_now = db.config.get("transition_type", "black") if db is not None else "black"
    if is_boot:
        app_state["_boot_suppress_static"] = True
    elif internal_advance:
        app_state["_boot_suppress_static"] = True
    elif _transition_style_now == "static":
        app_state["_boot_suppress_static"] = False
        app_state["channel_switch_black_until"] = pygame.time.get_ticks() + STATIC_TRANSITION_MS
        if new_ch == "04" and old_ch != "04":
            app_state["guide_entry_static_suppress_until"] = (
                app_state["channel_switch_black_until"] + 1500)
        if _warm_continue_skip_stop and vlc_engine is not None:
            try:
                vlc_engine.player.audio_set_mute(True)
            except Exception:
                pass
            app_state["_warm_static_mute_active"] = True
            _mute_guard_log("ARM (warm static transition duck)", ch=new_ch)
    elif is_surfing:
        app_state["_boot_suppress_static"] = False
        # WARNING: do not overwrite the shield the guide-exit warm-continuation branch above already armed.
        if not _guide_exit_warm_skip_stop:
            app_state["channel_switch_black_until"] = pygame.time.get_ticks() + 200
    else:
        app_state["_boot_suppress_static"] = False
        if not _guide_exit_warm_skip_stop:
            app_state["channel_switch_black_until"] = pygame.time.get_ticks() + 150

    if new_ch != "04" and not internal_advance:
        _prime_channel_block_durations(new_ch, synchronous=is_boot)

    _effective_snap = internal_advance if snap_internal_advance is None else snap_internal_advance
    
    try:
        t_state = calculate_slotted_playback_state(
            new_ch, snap_internal_advance=_effective_snap, trust_recent_stop=_fresh_self_anchor,
            allow_cold_anchor_resume=is_boot,
        )
    except Exception as _sched_err:
        log.error(
            "change_channel: calculate_slotted_playback_state raised for "
            "ch%s -- falling back to Static instead of crashing the "
            "channel switch: %s",
            new_ch, _sched_err, exc_info=True,
        )
        t_state = {
            "mode": "Static", "file": "", "seek": 0,
            "reason": "scheduler_exception",
            "reason_detail": f"CH{str(new_ch).zfill(2)}: scheduler raised {type(_sched_err).__name__}: {_sched_err}",
        }
    
    if new_ch == "04":
        t_state["mode"] = "Static"
        t_state["file"] = ""
        t_state["seek"] = 0
        
    _t_state_at = time.monotonic()
    next_track_path = t_state.get("file", "")

    if (new_ch != "04" and not internal_advance
            and t_state.get("mode") in ("Video", "Visualizer") and next_track_path):
        try:
            _prime_block = t_state.get("block") or (
                "Music Tracks" if t_state.get("mode") == "Visualizer" else None
            )
            if t_state.get("mode") == "Video":
                _prime_channel_picture_box(new_ch, next_track_path)
            _prime_channel_block_loudness(new_ch, next_track_path, _prime_block)
            if t_state.get("mode") == "Visualizer":
                _prime_visualizer_lookahead_loudness(new_ch, next_track_path)
        except Exception as _gain_prime_err:
            log.warning("change_channel: gain priming dispatch failed for ch%s: %s",
                        new_ch, _gain_prime_err)
    
    
        
    try:
        old_ch_info = db.channels_db.get(str(old_ch).zfill(2), {}) if db is not None else {}
        if (old_ch_info.get("is_visualizer", False) and new_ch != "04") or (new_ch == "04" and old_ch != "04" and not old_ch_info.get("is_visualizer", False)):
            if next_track_path != current_playing_track or not pygame.mixer.music.get_busy():
                pygame.mixer.Channel(1).stop()
                if pygame.mixer.music.get_busy():
                    pygame.mixer.music.stop()
    except Exception as e: log.warning(f"[CHANNEL] visualizer music stop failed: {e}")

    ch_info = db.channels_db.get(str(new_ch).zfill(2), {}) if db is not None else {}
    if not ch_info.get("is_visualizer", False) and new_ch != "04":
        app_state["persistent_track_pool_cache"] = ""
        
    app_state["digit_buffer"] = ""
    app_state["digit_timer"] = 0

    app_state["_last_new_frame_ticks"] = pygame.time.get_ticks()
    app_state["_stall_recovery_inflight"] = False
    app_state["_had_first_frame_this_tune"] = False

    if internal_advance:
        pass
    else:
        app_state["osd_channel_pending"] = False
        app_state["osd_channel_timer"] = pygame.time.get_ticks() + 2500
    if not internal_advance:
        app_state["visualizer_osd_timer"] = pygame.time.get_ticks() + 10000
    
    if new_ch == "04":
        app_state["selected_guide_time_idx"] = 0
        app_state["guide_col_pos"] = 0
        app_state["guide_selected_stop_key"] = None
        app_state["guide_selected_abs_time"] = None
        app_state["guide_col_anchor_abs"] = None
        app_state["guide_inactivity_timer"] = pygame.time.get_ticks() + 60000

        if not _guide_entry_warm_skip_stop:
            app_state["loaded_preview_path_cache"] = ""
            app_state["guide_preview_loading"] = False
            app_state["guide_preview_load_started_ms"] = 0
        if old_ch != "04" and not _guide_entry_warm_skip_stop:
            _clear_last_video_frame(context="preview")

        if old_ch and old_ch != "04":
            _existing = str(app_state.get("highlighted_guide_channel", "05")).zfill(2)
            try:
                if int(_existing) < 5:
                    _existing = "05"
            except (ValueError, TypeError):
                _existing = "05"
            app_state["highlighted_guide_channel"] = _existing
            app_state["selected_guide_channel"]    = int(_existing)
            _allowed_guide_restore = [
                str(i).zfill(2) for i in range(5, 45)
                if db.channels_db.get(str(i).zfill(2), {}).get("active", True)
            ] if db is not None else []
            try:
                _restore_pos = _allowed_guide_restore.index(_existing)
            except ValueError:
                _restore_pos = 0
            _guide_rows_restore = get_guide_visible_rows(db)
            _cur_offset = app_state.get("guide_row_offset", 0)
            if _restore_pos < _cur_offset or _restore_pos >= _cur_offset + _guide_rows_restore:
                app_state["guide_row_offset"] = max(0, _restore_pos - (_guide_rows_restore - 1))

        _resync_guide_stop_after_row_switch()

        _guide_target_hl = str(app_state.get("highlighted_guide_channel", 5)).zfill(2)
        _guide_target_hl_clamped = _guide_target_hl
        try:
            if int(_guide_target_hl_clamped) < 5:
                _guide_target_hl_clamped = "05"
        except (ValueError, TypeError):
            _guide_target_hl_clamped = "05"
        if (_outgoing_live_snapshot is not None
                and _guide_target_hl_clamped == str(old_ch).zfill(2)):
            guide_target = {
                "mode": _outgoing_live_snapshot.get("mode", "Video"),
                "file": _outgoing_live_snapshot["file"],
                "seek": _outgoing_live_snapshot["pos"],
                "duration": _outgoing_live_snapshot["duration"],
            }
        else:
            guide_target = calculate_slotted_playback_state(_guide_target_hl)
        if pygame.mixer.music.get_busy() and guide_target.get("file") != current_playing_track:
            pygame.mixer.music.stop()
        if not _guide_entry_warm_skip_music_stop:
            app_state["guide_preview_music_track"] = ""

        if _guide_entry_warm_skip_stop and _guide_entry_warm_target_file:
            app_state["loaded_preview_path_cache"] = _guide_entry_warm_target_file
            app_state["_live_playback_channel"] = str(old_ch).zfill(2)
            print(f"[GUIDE ENTRY WARM] highlight already matches live playback -- "
                  f"skipping reload for {_guide_entry_warm_target_file}")

            # WARNING: this is the one transition path that never calls play_file_segmented() again.
            _warm_transition_style = db.config.get("transition_type", "black") if db is not None else "black"
            if _warm_transition_style == "static":
                _warm_burst_ms = STATIC_TRANSITION_MS
                app_state["guide_preview_static_until"] = pygame.time.get_ticks() + _warm_burst_ms
                app_state["guide_preview_black_until"] = 0
            else:
                _warm_burst_ms = GUIDE_PREVIEW_SETTLE_MS
                app_state["guide_preview_black_until"] = pygame.time.get_ticks() + _warm_burst_ms
                app_state["guide_preview_static_until"] = 0
            app_state["channel_switch_black_until"] = pygame.time.get_ticks() + _warm_burst_ms
            # WARNING: the shield's own timer owns unmuting here, not the readiness lifter.
            app_state["_video_pending_unmute"] = False
            _arm_warm_transition_shield(vlc_engine, _warm_burst_ms)
            _mute_guard_log("ARM (guide-entry warm transition shield)", ch=old_ch)
    else:
        app_state["guide_col_pos"] = 0
        app_state["guide_row_offset"] = 0
        app_state["guide_selected_stop_key"] = None
        app_state["guide_selected_abs_time"] = None
        app_state["guide_col_anchor_abs"] = None

    if new_ch == "04":
        _guide_dirty_event.set()

    _content_activate = None
    _content_activate_concurrent_safe = False
    if t_state["mode"] in ("Video", "Commercial"):
        initialize_vlc_on_demand()

        if vlc_engine is None:
            print(f"[VLC WAIT] Engine still initializing for channel {new_ch}...")
            app_state["is_playing_video"] = False
            app_state["last_vlc_retry_at"] = pygame.time.get_ticks()
        else:
            app_state["last_vlc_retry_at"] = pygame.time.get_ticks()

            _cc_station_ch_key = str(new_ch).zfill(2)
            _cc_station_dead_root = _station_confirmed_dead_drive.get(_cc_station_ch_key)
            if _cc_station_dead_root is not None and _drive_confirmed_recovered(_cc_station_dead_root):
                _station_confirmed_dead_drive.pop(_cc_station_ch_key, None)
                _clear_broken_files_for_root(_cc_station_dead_root)
                _cc_station_dead_root = None
            _cc_station_drive_confirmed_dead = _cc_station_dead_root is not None
            if _cc_station_drive_confirmed_dead:
                # WARNING: a dead root latched here never appears in _unresponsive_drive_roots(), so recovery never fires and the channel stays stuck until restart.
                log.warning(
                    "[DRIVE LATCH] change_channel: channel %s latched dead on "
                    "drive %r (a prior load attempt failed and never got a "
                    "recovery signal) -- skipping straight to Static instead "
                    "of attempting to play. Currently unresponsive drive roots: "
                    "%s. Ever-confirmed-unresponsive roots: %s. If %r never "
                    "appears in either set, this channel cannot self-recover "
                    "without an app restart.",
                    _cc_station_ch_key, _cc_station_dead_root,
                    _unresponsive_drive_roots(), sorted(_drive_ever_confirmed_unresponsive),
                    _cc_station_dead_root,
                )

            def _content_activate(new_ch=new_ch, t_state=dict(t_state), force_reload=force_reload,
                                   _drive_confirmed_dead=_cc_station_drive_confirmed_dead,
                                   _ch_key=_cc_station_ch_key):
                if _drive_confirmed_dead:
                    app_state["is_playing_video"] = False
                    _register_channel_playback_failure(
                        _ch_key, t_state.get("file", ""),
                        duration=t_state.get("duration"), block=t_state.get("block"),
                    )
                    return
                try:
                    import vlc
                    current_media = vlc_engine.player.get_media()
                    current_path = ""
                    if current_media:
                        from urllib.parse import unquote
                        current_path = os.path.normpath(unquote(current_media.get_mrl().replace("file:///", ""))).lower()
                    target_path = os.path.normpath(t_state["file"]).lower()

                    _should_play = force_reload or current_path != target_path or (
                        vlc_engine.player.get_state() not in [vlc.State.Playing, vlc.State.Opening])

                    _cc_ch_key = str(new_ch).zfill(2)

                    def _make_cc_on_confirmed(_snap):
                        def _cc_on_confirmed(success, attempt_id, deferred, _s=_snap):
                            if success:
                                _confirm_playback_started(
                                    _cc_ch_key, attempt_id, _s.get("file"),
                                    _s.get("seek", 0), _s.get("seek_slot_offset", 0),
                                    _s.get("duration", 1800), _s.get("mode", "Video"),
                                    _s.get("block", "Morning"), _s.get("interior_cut", False),
                                    deferred,
                                )
                            else:
                                _confirm_playback_failed(_cc_ch_key, attempt_id, _s.get("file"), deferred,
                                                          reason="change_channel_open_failed")
                        return _cc_on_confirmed

                    _played_ok = True
                    if _should_play:
                        _sg_guard = 0
                        while _sg_guard < 3:
                            _sg_guard += 1
                            _sg_file = t_state.get("file")
                            if not _sg_file:
                                break
                            _sg_norm = os.path.normpath(str(_sg_file))
                            _sg_probe = _get_cached_media_probe(_sg_norm)
                            _sg_real_dur = _sg_probe.get("duration") if _sg_probe else None
                            if not _sg_real_dur:
                                _sg_real_dur = _probe_duration_seconds_fast(_sg_norm)
                            if (_sg_real_dur
                                    and t_state.get("seek", 0) >= _sg_real_dur - _SEEK_GUARD_TAIL_MARGIN_S):
                                _sg_real_dur = _probe_duration_seconds_fast(_sg_norm) or _sg_real_dur
                            if not _sg_real_dur or t_state.get("seek", 0) < _sg_real_dur - _SEEK_GUARD_TAIL_MARGIN_S:
                                break
                            
                            try:
                                _patch_probed_gain(
                                    "channel", str(new_ch).zfill(2), t_state.get("block", "Morning"),
                                    _sg_norm, gain=None, duration=_sg_real_dur,
                                )
                            except Exception as _sg_patch_err:
                                log.warning("change_channel: seek-guard duration patch failed for ch%s: %s", new_ch, _sg_patch_err)
                                break
                            _refreshed_state = calculate_slotted_playback_state(
                                new_ch
                            )
                            # WARNING: a duration correction must not turn a valid selected file into an empty Static state.
                            if _refreshed_state.get("file"):
                                t_state = _refreshed_state
                            else:
                                t_state["seek"] = 0
                                log.warning(
                                    "change_channel: schedule refresh returned "
                                    "no file for ch%s; retaining current media "
                                    "after duration correction",
                                    new_ch,
                                )
                        target_path = os.path.normpath(t_state.get("file", "")).lower()

                        if not t_state.get("file"):
                            log.warning(
                                "change_channel: refusing empty playback state "
                                "for channel %s",
                                new_ch,
                            )
                            _played_ok = False
                            raise RuntimeError(
                                "empty playback state returned by scheduler"
                            )

                        if vlc_engine.player.is_playing():
                            vlc_engine.stop(block=False)
                        vlc_engine.set_volume(db.config["global_volume"], db.config.get("is_muted", False))

                        try: vlc_engine.player.audio_set_mute(True)
                        except Exception: pass
                        app_state["_video_pending_unmute"] = True
                        app_state["_video_audio_hold_until"] = max(
                            app_state.get("_video_audio_hold_until", 0),
                            pygame.time.get_ticks() + AUDIO_SYNC_HOLD_MS,
                        )
                        app_state["last_video_play_started_at"] = pygame.time.get_ticks()
                        _mute_guard_log("ARM (real channel change)", ch=new_ch, filepath=t_state["file"])
                        _played_ok = vlc_engine.play_file_segmented(
                            t_state["file"], t_state["seek"],
                            gain=_lookup_file_gain(new_ch, t_state["file"]),
                            defer_unmute=True,
                            on_confirmed=_make_cc_on_confirmed(dict(t_state)),
                        )

                        try:
                            vlc_engine.player.audio_set_mute(True)
                        except Exception:
                            pass

                        _arm_mute_guard_watchdog(new_ch, t_state["file"])

                        _ch_key_for_retry = str(new_ch).zfill(2)
                        _retry_guard = 0
                        _retry_deadline_ms = pygame.time.get_ticks() + 5000
                        _retry_drive_fail_counts = {}
                        _RETRY_DRIVE_BAIL_AFTER = 2
                        while (_played_ok is False and db is not None and _retry_guard < 200
                               and pygame.time.get_ticks() < _retry_deadline_ms):
                            _retry_guard += 1

                            try:
                                _retry_fail_root = media._drive_root_of(t_state.get("file"))
                            except Exception:
                                _retry_fail_root = None
                            _retry_bail_reason = None
                            if _retry_fail_root and _retry_fail_root in _unresponsive_drive_roots():
                                _retry_bail_reason = "flagged unresponsive by the drive health monitor"
                            elif _retry_fail_root:
                                _retry_drive_fail_counts[_retry_fail_root] = (
                                    _retry_drive_fail_counts.get(_retry_fail_root, 0) + 1
                                )
                                if _retry_drive_fail_counts[_retry_fail_root] >= _RETRY_DRIVE_BAIL_AFTER:
                                    _retry_bail_reason = (
                                        f"{_retry_drive_fail_counts[_retry_fail_root]} consecutive "
                                        f"failures observed on it"
                                    )
                            if _retry_bail_reason is not None:
                                log.warning(
                                    "change_channel: '%s' is on drive %s -- %s -- "
                                    "abandoning substitute search for channel %s after %d "
                                    "attempt(s) rather than continuing to retry against a "
                                    "dead drive.",
                                    t_state.get("file"), _retry_fail_root, _retry_bail_reason,
                                    new_ch, _retry_guard,
                                )
                                _register_channel_playback_failure(
                                    _ch_key_for_retry, t_state["file"],
                                    duration=t_state.get("duration"),
                                    block=t_state.get("block"),
                                )
                                if _retry_fail_root:
                                    _station_confirmed_dead_drive[_ch_key_for_retry] = _retry_fail_root
                                    _remember_dead_drive_probe_file(_retry_fail_root, t_state.get("file"))
                                break

                            _ch_info_live = db.channels_db.get(_ch_key_for_retry, {})
                            _sub = _resolve_broken_episode(_ch_info_live, t_state["file"], t_state.get("block", "Morning"), channel_id=_ch_key_for_retry)
                            if _sub is None:
                                log.warning(
                                    "change_channel: no playable substitute left for channel %s "
                                    "(file %s) -- leaving black-screen protection engaged.",
                                    new_ch, t_state["file"])
                                _register_channel_playback_failure(
                                    _ch_key_for_retry, t_state["file"],
                                    duration=t_state.get("duration"),
                                    block=t_state.get("block"),
                                )
                                break
                            _log_warn_throttled("rtv_L13300", f"[BLACK SCREEN FIX] '{t_state['file']}' failed to play -- "
                                  f"substituting '{_sub['file']}' and rescheduling future slots.")
                            t_state["file"] = _sub["file"]
                            t_state["seek"] = _sub["seek"]
                            t_state["duration"] = _sub["duration"]
                            app_state["last_video_play_started_at"] = pygame.time.get_ticks()
                            _played_ok = vlc_engine.play_file_segmented(
                                t_state["file"], t_state["seek"],
                                gain=_lookup_file_gain(new_ch, t_state["file"]),
                                defer_unmute=True,
                                on_confirmed=_make_cc_on_confirmed(dict(t_state)),
                            )

                    if not _should_play:
                        _anchor_seek = t_state.get("seek", 0)
                        try:
                            _real_ms = vlc_engine.player.get_time()
                            if _real_ms is not None and _real_ms >= 0:
                                _anchor_seek = _real_ms / 1000.0
                        except Exception as _pos_err:
                            log.warning(
                                "change_channel: could not read real VLC position for "
                                "ch%s anchor, falling back to computed seek: %s",
                                new_ch, _pos_err)
                        _confirm_playback_started(
                            _cc_ch_key, getattr(vlc_engine, "_current_attempt_id", None),
                            t_state.get("file"), _anchor_seek, t_state.get("seek_slot_offset", 0),
                            t_state.get("duration", 1800), t_state.get("mode", "Video"),
                            t_state.get("block", "Morning"), t_state.get("interior_cut", False),
                            False,
                        )
                except Exception as e:
                    log.warning(f"[VLC ERROR] Failed to play video on channel {new_ch}: {e}")
                    log.warning("change_channel: exception while starting video on ch%s: %s", new_ch, e)
                    app_state["is_playing_video"] = False
            _content_activate_concurrent_safe = _content_activate is not None
            if _content_activate_concurrent_safe:
                app_state["_video_audio_hold_until"] = max(
                    app_state.get("_video_audio_hold_until", 0),
                    pygame.time.get_ticks() + AUDIO_SYNC_HOLD_MS,
                )
    else:
        if t_state["mode"] == "Visualizer":
            track_file_path = t_state.get("file", "")
            track_seek_start = t_state.get("seek", 0)
            track_total_len = t_state.get("duration", 210)
            app_state["music_owner"] = "live_visualizer"
            app_state["vis_song_started_at"] = pygame.time.get_ticks()

            _cc_vis_ch_key = str(new_ch).zfill(2)
            _cc_vis_dead_root = _visualizer_confirmed_dead_drive.get(_cc_vis_ch_key)
            if _cc_vis_dead_root is not None and _drive_confirmed_recovered(_cc_vis_dead_root):
                _visualizer_confirmed_dead_drive.pop(_cc_vis_ch_key, None)
                _cc_vis_dead_root = None
            _cc_vis_drive_confirmed_dead = _cc_vis_dead_root is not None

            if track_file_path:
                app_state["active_music_track_file"] = track_file_path
                

                if db is not None:
                    _wall_va = broadcast_clock.seconds_since_midnight()
                    db.channels_db[str(new_ch).zfill(2)]["playback_anchor"] = {
                        "file":        track_file_path,
                        "wall_start":  _wall_va,
                        "seek_offset": track_seek_start,
                        "duration":    track_total_len,
                        "mode":        "Visualizer",
                        "block":       t_state.get("block", "Morning"),
                        "anchor_written_at": broadcast_clock.now().timestamp(),
                    }
                    try:
                        db.save_playback_anchor()
                    except Exception as e:
                        log.warning("change_channel: failed to persist new visualizer playback_anchor for ch%s: %s", new_ch, e)
            else:
                pass
            
            if _cc_vis_drive_confirmed_dead:
                if pygame.mixer.music.get_busy():
                    pygame.mixer.music.stop()
                app_state["active_music_track_file"] = ""
                app_state["music_owner"] = ""
            elif _guide_exit_warm_skip_music_stop:
                pass
            elif track_file_path and (track_file_path != current_playing_track or not pygame.mixer.music.get_busy()):
                
                if pygame.mixer.music.get_busy(): pygame.mixer.music.stop()
                _load_ok = False
                _vis_playback_path = _resolve_compressor_playback_path(track_file_path, for_seek=True)
                try:
                    pygame.mixer.music.load(_vis_playback_path)
                    app_state["_music_loaded_playback_path"] = _vis_playback_path
                    _load_ok = True
                except Exception as load_err:
                    log.warning(f"[VISUALIZER CHANNEL] Music load failed for {_vis_playback_path}: {load_err}")
                if _load_ok:
                    app_state["active_music_gain"] = _lookup_file_gain(new_ch, track_file_path)
                    safe_seek_pos = max(0.0, min(float(track_seek_start), float(track_total_len) - 1.0))
                    _vis_seek_t0 = _t_state_at
                    _real_music_vol = (
                        _effective_audio_gain(min_db=STACKED_GAIN_MIN_DB)
                        * MUSIC_GAIN
                        * _effective_loudness_gain(app_state["active_music_gain"])
                    )

                    _vis_duck_for_static = (_transition_style_now == "static")

                    def _content_activate(safe_seek_pos=safe_seek_pos, _real_music_vol=_real_music_vol,
                                          _vis_seek_t0=_vis_seek_t0, _vis_len=track_total_len,
                                          _duck=_vis_duck_for_static,
                                          _dbg_ch=str(new_ch).zfill(2), _dbg_file=track_file_path,
                                          _dbg_len=track_total_len):
                        pygame.mixer.music.set_volume(0.0 if _duck else _real_music_vol)
                        if _duck:
                            app_state["_visualizer_pending_music_vol"] = _real_music_vol
                            app_state["_visualizer_audio_duck_active"] = True
                        try:
                            # WARNING: the seek was computed before the tune-in transition ran; add the time that has passed so the song lands where the schedule is now.
                            safe_seek_pos = max(0.0, min(safe_seek_pos + (time.monotonic() - _vis_seek_t0), float(_vis_len) - 1.0))
                            if _start_visualizer_music(_dbg_file, safe_seek_pos) is False:
                                app_state["active_music_track_file"] = ""
                                app_state["music_owner"] = ""
                        except Exception as play_err:
                            log.warning(f"[VISUALIZER CHANNEL] tune-in play failed for {_dbg_file}: {play_err}")

                # WARNING: protect the text string from being blanked by the audio mixer load wipe.
                app_state["active_music_track_file"] = track_file_path
                app_state["vis_card_timer"] = pygame.time.get_ticks() + 15000
            else:
                
                app_state["vis_card_timer"] = pygame.time.get_ticks() + 15000
        else:
            if vlc_engine is not None and not _guide_entry_warm_skip_stop:
                try:
                    if vlc_engine.player.is_playing():
                        try:
                            vlc_engine.player.audio_set_mute(True)
                        except Exception as e:
                            log.warning(f"[CHANNEL] pre-stop mute failed (non-video landing): {e}")
                        vlc_engine.stop(block=False)
                        pygame.time.wait(100)
                except Exception as e: log.warning(f"[CHANNEL] vlc stop on switch failed: {e}")

            if (new_ch == "04" and not _guide_entry_warm_skip_stop
                    and vlc_engine is not None
                    and guide_target.get("mode") in ("Video", "Commercial")
                    and guide_target.get("file")):
                _start_guide_preview_load(
                    str(app_state.get("highlighted_guide_channel", "05")).zfill(2),
                    guide_target,
                )

            global _channel_activation_generation
            _channel_activation_generation += 1
        app_state["is_playing_video"] = False
        print(f"[CHANNEL] Switched to non-video channel {new_ch}")
        
    _dvd_resume_activate = None
    if new_ch == "03" and game_deck is not None and getattr(game_deck, 'dvd_playback_active', False) and getattr(game_deck, 'dvd_file_path', ''):
        initialize_vlc_on_demand()

        if dvd_engine is not None:
            def _dvd_resume_activate():
                try:
                    dvd_engine.player.audio_set_mute(False)
                    dvd_engine.set_volume(db.config["global_volume"] if db else 70,
                                          db.config.get("is_muted", False) if db else False)
                    game_deck.dvd_iso_backgrounded = False
                    game_deck.dvd_exit_confirm = False
                    game_deck.dvd_awaiting_resume = False
                    game_deck.dvd_resume_pending = False
                    print("[DVD] Background resume: dvd_engine unmuted in place, no reopen needed.")
                except Exception as _ue:
                    log.warning(f"[DVD] Background resume unmute failed: {_ue}")

    if _content_activate_concurrent_safe and _content_activate is not None:
        _dispatch_content_activation(_content_activate)
        _content_activate = None

    def _activate_pending():
        if _ch03_activate is not None:
            _ch03_activate()
        if _content_activate is not None:
            _dispatch_content_activation(_content_activate)
        if _dvd_resume_activate is not None:
            _dvd_resume_activate()
    app_state["_pending_channel_activation"] = _activate_pending

    
    

    pygame.event.pump()


# ============================================================================
# SECTION: Channel counts & surf-up helpers
# ============================================================================


def _count_active_content_channels(db):
    """Return how many channels in 05-44 range are currently active."""
    if db is None: return 1
    count = 0
    for n in range(5, 45):
        ch_str = str(n).zfill(2)
        ch = db.channels_db.get(ch_str, {})
        if ch.get('active', ch_str == '05'):
            count += 1
    return count


def _count_active_consoles(db):
    """Return how many consoles in CONSOLE_ORDER are currently enabled."""
    if db is None: return 1
    from game_deck import CONSOLE_ORDER
    enabled_map = db.config.get("consoles_enabled", {})
    count = 0
    for c in CONSOLE_ORDER:
        if c == "MENU":
            continue
        default_on = (c == "DVD")
        if enabled_map.get(c, default_on):
            count += 1
    return count


def _surf_up_from_disabled(off_ch):
    off_str = str(off_ch).zfill(2)
    if str(app_state.get("current_channel", "05")).zfill(2) != off_str:
        return

    allowed = []
    if db is not None and db.config.get("game_channel_enabled", True):
        allowed.append("03")
    if db is not None and db.config.get("tv_guide_enabled", True):
        allowed.append("04")
    if db is not None:
        for i in range(5, 45):
            ch_key = str(i).zfill(2)
            if db.channels_db.get(ch_key, {}).get("active", False):
                allowed.append(ch_key)

    if not allowed:
        return

    target = next((ch for ch in allowed if int(ch) > int(off_str)), allowed[0])
    print(f"[CHANNEL] {off_str} turned off while watching — surfing up to {target}.")
    change_channel(target, is_surfing=True)


# ============================================================================
# SECTION: Stall recovery & VLC engine rebuild
# ============================================================================


def _recover_from_playback_stall(stalled_ch, stalled_ms):
    print(f"[STALL WATCHDOG] Channel {stalled_ch} produced no new frame for "
          f"{stalled_ms}ms (>= {PLAYBACK_STALL_TIMEOUT_MS}ms threshold) — "
          f"recovering by moving to the next active channel.")

    allowed = []
    if db is not None and db.config.get("game_channel_enabled", True):
        allowed.append("03")
    if db is not None and db.config.get("tv_guide_enabled", True):
        allowed.append("04")
    if db is not None:
        for i in range(5, 45):
            ch_key = str(i).zfill(2)
            if db.channels_db.get(ch_key, {}).get("active", False):
                allowed.append(ch_key)

    stalled_str = str(stalled_ch).zfill(2)
    allowed = [c for c in allowed if c != stalled_str]

    if not allowed:
        print("[STALL WATCHDOG] No other active channel to recover to — "
              "holding on the stalled channel and resetting the stall clock.")
        app_state["_stall_recovery_inflight"] = False
        app_state["_last_new_frame_ticks"] = pygame.time.get_ticks()
        return

    target = next((ch for ch in allowed if int(ch) > int(stalled_str)), allowed[0])
    app_state["_stall_recovery_inflight"] = False
    change_channel(target, is_surfing=True)
    if vlc_engine is not None and getattr(vlc_engine, "_wedged", False):
        _replace_wedged_vlc_engine()


_wedged_engine_replacement_inflight = False


def _replace_wedged_vlc_engine():
    global _wedged_engine_replacement_inflight
    if _wedged_engine_replacement_inflight:
        return
    _wedged_engine_replacement_inflight = True
    _dead_engine = vlc_engine
    log.critical("[WEDGED-TEARDOWN] Building a replacement VLC engine in the "
                 "background; the old '%s' engine is being abandoned.",
                 getattr(_dead_engine, "engine_label", "?"))

    def _build_and_swap():
        global vlc_engine, _wedged_engine_replacement_inflight
        try:
            if _VLCEngineWrapperClass is None:
                raise RuntimeError(
                    "VLCEngineWrapper class unavailable -- "
                    "initialize_vlc_on_demand() has not completed successfully")
            _recovered_args = list(_vlc_base_args_main or []) + _compressor_filter_args() + _stereo_mode_args()
            _new_engine = _VLCEngineWrapperClass(instance_args=_recovered_args, engine_label="main-recovered")
            vlc_engine = _new_engine
            log.critical("[WEDGED-TEARDOWN] Replacement engine ready -- "
                         "swapped in. Re-tuning current channel to resume playback.")
            try:
                change_channel(app_state.get("current_channel", "05"), force_reload=True)
            except Exception as _e:
                log.warning("[WEDGED-TEARDOWN] Re-tune after engine swap failed: %s", _e)
        except Exception as _e:
            log.critical("[WEDGED-TEARDOWN] Failed to build replacement engine: %s", _e)
        finally:
            _wedged_engine_replacement_inflight = False

    threading.Thread(target=_build_and_swap, daemon=True,
                      name="vlc-engine-recovery").start()


_loudness_rebuild_inflight = False
_dvd_engine_rebuild_deferred = False


# ============================================================================
# SECTION: Loudness toggle, engine rebuild without interrupting playback
# ============================================================================


def _loudness_hold_last_frame_ms():
    """The governor's time the last picture stays on screen while a loudness engine rebuild reopens the show."""
    # WARNING: the 3000 fallback must match LOUDNESS_HOLD_LAST_FRAME_MS in performance_governor.py; it is used only when that module fails to import.
    return int(performance_governor.LOUDNESS_HOLD_LAST_FRAME_MS) if performance_governor is not None else 3000


def _loudness_hold_last_frame_active():
    """True while the last picture stays on screen because a loudness engine rebuild is reopening the show."""
    return pygame.time.get_ticks() < app_state.get("_hold_last_frame_until", 0)


def _loudness_retune_kind(ch):
    """What the engine swap does for channel ch: "video" reopens the show, "guide" reopens the guide preview, "none" leaves playback alone."""
    ch = str(ch).zfill(2)
    if ch == "04":
        return "guide"
    if ch == "03" or db is None:
        return "none"
    if db.channels_db.get(ch, {}).get("is_visualizer", False):
        return "none"
    return "video"


def _dvd_loudness_rebuild_plan():
    """Decides what a loudness toggle does to the DVD engine: "rebuild" (nothing is playing on it), "resume" (a plain video file plays in front: rebuild, then rejoin it), "defer" (a disc, a disc image or a backgrounded file plays: leave it untouched until it stops)."""
    if (game_deck is None or getattr(game_deck, "mode", None) != "DVD_PLAYER"
            or not getattr(game_deck, "dvd_file_path", None)
            or not getattr(game_deck, "dvd_playback_active", False)):
        return "rebuild"
    if getattr(game_deck, "dvd_is_disc_image", False) or getattr(game_deck, "dvd_iso_backgrounded", False):
        return "defer"
    return "resume"


def _rebuild_vlc_engines_for_loudness_toggle(rebuild_main=True):
    """Rebuilds the main and DVD VLC engines so the live compressor filter is added or removed; the show on screen is reopened at its scheduled second."""
    # WARNING: libvlc reads --audio-filter only when vlc.Instance() is constructed, so a loudness_scan_enabled flip must rebuild the engine.
    global _loudness_rebuild_inflight, _wedged_engine_replacement_inflight, _dvd_engine_rebuild_deferred
    if _loudness_rebuild_inflight or _wedged_engine_replacement_inflight:
        log.info("[LOUDNESS] Engine rebuild already in progress; skipping duplicate request.")
        return
    if _VLCEngineWrapperClass is None:
        _log_warn_throttled("loudness_rebuild_no_class",
                             "[LOUDNESS] Rebuild requested but VLCEngineWrapper "
                             "class unavailable -- no engine to rebuild yet.")
        return

    _old_main = vlc_engine if rebuild_main else None
    _old_dvd = dvd_engine
    _dvd_plan = _dvd_loudness_rebuild_plan() if _old_dvd is not None else "rebuild"
    if _old_dvd is not None and _dvd_plan == "defer":
        _dvd_engine_rebuild_deferred = True
        _old_dvd = None
        log.info("[LOUDNESS] DVD engine left untouched while a disc or background file plays; it is rebuilt once it stops.")
    elif _old_dvd is not None:
        _dvd_engine_rebuild_deferred = False
    if _old_main is None and _old_dvd is None:
        return

    _loudness_rebuild_inflight = True
    _wedged_engine_replacement_inflight = True

    _dvd_resume_seconds = None
    _dvd_resume_file = None
    _dvd_needs_menu_restart = False
    _dvd_captured_at = 0.0
    try:
        if _dvd_plan == "resume" and _old_dvd is not None:
            _dvd_resume_file = game_deck.dvd_file_path
            if (not getattr(game_deck, "dvd_in_menu", False)
                    and not getattr(game_deck, "dvd_splash_playing", False)):
                try:
                    _t_ms = _old_dvd.player.get_time()
                except Exception:
                    _t_ms = None
                _dvd_resume_seconds = (_t_ms / 1000.0) if _t_ms and _t_ms > 0 else 0
                _dvd_captured_at = time.monotonic()
            else:
                _dvd_needs_menu_restart = True
    except Exception as _e:
        _log_warn_throttled("loudness_rebuild_dvd_state_capture",
                             "[LOUDNESS] Failed to capture DVD state before engine rebuild: %s", _e)

    log.info("[LOUDNESS] Rebuilding VLC engines: compressor=%s stereo_mode=%s.",
             "enable" if _compressor_filter_args() else "disable",
             "mono" if _stereo_mode_args() else "stereo")

    def _build_engines():
        global _pending_loudness_engine_swap

        _new_main = None
        _new_dvd = None
        # WARNING: keep separate from "_new_main/_new_dvd succeeded"; never conflate them.
        _abandoned_main = None
        _abandoned_dvd = None

        if _old_main is not None:
            try:
                _new_main_args = list(_vlc_base_args_main or []) + _compressor_filter_args() + _stereo_mode_args()
                _new_main = _VLCEngineWrapperClass(instance_args=_new_main_args, engine_label="main")
                _abandoned_main = _old_main
            except Exception as e:
                _log_warn_throttled("loudness_rebuild_main_engine",
                                     "[LOUDNESS] Main engine rebuild failed, keeping old engine running: %s", e)
                _new_main = None

        if _old_dvd is not None:
            try:
                _new_dvd_args = list(_vlc_base_args_dvd or []) + _compressor_filter_args() + _stereo_mode_args()
                _new_dvd = _VLCEngineWrapperClass(instance_args=_new_dvd_args, engine_label="dvd")
                _abandoned_dvd = _old_dvd
            except Exception as e:
                _log_warn_throttled("loudness_rebuild_dvd_engine",
                                     "[LOUDNESS] DVD engine rebuild failed, keeping old engine running: %s", e)
                _new_dvd = None

        def _swap_in_on_main_thread():
            global vlc_engine, dvd_engine, _loudness_rebuild_inflight, _wedged_engine_replacement_inflight
            try:
                if _new_main is not None:
                    vlc_engine = _new_main
                if _new_dvd is not None:
                    dvd_engine = _new_dvd
                    if game_deck is not None:
                        game_deck.vlc_engine = dvd_engine
                        game_deck.dvd_gain_lookup = _get_or_queue_dvd_gain

                for _silence_eng in (_abandoned_main, _abandoned_dvd):
                    if _silence_eng is None:
                        continue
                    try:
                        _silence_eng.player.audio_set_mute(True)
                    except Exception as _e:
                        _log_warn_throttled("loudness_rebuild_old_engine_mute",
                                             "[LOUDNESS] Pre-close mute of replaced '%s' engine failed: %s",
                                             getattr(_silence_eng, "engine_label", "?"), _e)

                def _close_old_engines():
                    for _eng in (_abandoned_main, _abandoned_dvd):
                        if _eng is None:
                            continue
                        try:
                            _eng.close()
                        except Exception as _e:
                            _log_warn_throttled("loudness_rebuild_engine_close",
                                                 "[LOUDNESS] Closing replaced '%s' engine failed: %s",
                                                 getattr(_eng, "engine_label", "?"), _e)
                threading.Thread(target=_close_old_engines, daemon=True,
                                  name="vlc-loudness-rebuild-teardown").start()

                _retune_kind = _loudness_retune_kind(app_state.get("current_channel", "05"))
                if _new_main is not None and _retune_kind != "none":
                    if _retune_kind == "video":
                        app_state["_hold_last_frame_until"] = pygame.time.get_ticks() + _loudness_hold_last_frame_ms()
                    try:
                        change_channel(app_state.get("current_channel", "05"), force_reload=True,
                                        internal_advance=True, snap_internal_advance=False)
                    except Exception as e:
                        _log_warn_throttled("loudness_rebuild_retune",
                                             "[LOUDNESS] Re-tune after engine rebuild failed: %s", e)

                try:
                    if _dvd_resume_file and game_deck is not None and _new_dvd is not None:
                        if _dvd_needs_menu_restart:
                            game_deck._start_dvd_playback(_dvd_resume_file)
                        else:
                            game_deck._play_dvd_main(
                                seek_seconds=(_dvd_resume_seconds or 0)
                                + ((time.monotonic() - _dvd_captured_at) if _dvd_captured_at else 0.0))
                except Exception as e:
                    _log_warn_throttled("loudness_rebuild_dvd_resume",
                                         "[LOUDNESS] DVD resume after engine rebuild failed: %s", e)

                log.info("[LOUDNESS] VLC engine rebuild complete.")
            finally:
                _loudness_rebuild_inflight = False
                _wedged_engine_replacement_inflight = False

        _pending_loudness_engine_swap = _swap_in_on_main_thread

    threading.Thread(target=_build_engines, daemon=True,
                      name="vlc-loudness-rebuild-build").start()


_pending_loudness_engine_swap = None


def _run_pending_loudness_engine_swap():
    global _pending_loudness_engine_swap
    _fn = _pending_loudness_engine_swap
    if _fn is None:
        return
    _pending_loudness_engine_swap = None
    try:
        _fn()
    except Exception as e:
        log.warning("[LOUDNESS] pending engine swap failed: %s", e)


def _run_deferred_dvd_engine_rebuild():
    """Rebuilds the DVD engine once nothing plays on it, after a loudness toggle that had to leave a disc or a background file alone."""
    if not _dvd_engine_rebuild_deferred or _loudness_rebuild_inflight or _wedged_engine_replacement_inflight:
        return
    if game_deck is not None and getattr(game_deck, "dvd_playback_active", False):
        return
    _rebuild_vlc_engines_for_loudness_toggle(rebuild_main=False)


def _reload_visualizer_music_for_loudness_toggle():
    """Reloads the playing Visualizer song at its scheduled second when Loudness Scan changes which file the mixer must play; returns True when it reloaded."""
    if db is None or app_state.get("music_owner") != "live_visualizer" or not pygame.mixer.music.get_busy():
        return False
    _ch_key = str(app_state.get("current_channel", "")).zfill(2)
    _track = app_state.get("active_music_track_file", "")
    if not _track or not db.channels_db.get(_ch_key, {}).get("is_visualizer", False):
        return False
    _new_path = _resolve_compressor_playback_path(_track, for_seek=True)
    if _new_path == (app_state.get("_music_loaded_playback_path") or _track):
        return False
    _t0 = time.monotonic()
    _state = calculate_slotted_playback_state(_ch_key)
    if _state.get("mode") != "Visualizer" or _state.get("file") != _track:
        return False
    pygame.mixer.Channel(1).stop()
    pygame.mixer.music.stop()
    try:
        pygame.mixer.music.unload()
    except Exception as _unload_err:
        log.warning("[LOUDNESS] Visualizer song unload failed for %s: %s", _track, _unload_err)
    try:
        pygame.mixer.music.load(_new_path)
    except Exception as _load_err:
        log.warning("[LOUDNESS] Visualizer song reload failed for %s: %s", _track, _load_err)
        app_state["music_owner"] = ""
        return False
    app_state["_music_loaded_playback_path"] = _new_path
    app_state["active_music_gain"] = _lookup_file_gain(_ch_key, _track)
    pygame.mixer.music.set_volume(
        _effective_audio_gain(min_db=STACKED_GAIN_MIN_DB)
        * MUSIC_GAIN
        * _effective_loudness_gain(app_state["active_music_gain"])
    )
    _seek = max(0.0, min(float(_state.get("seek", 0)) + (time.monotonic() - _t0),
                         float(_state.get("duration", 210)) - 1.0))
    if _start_visualizer_music(_track, _seek) is False:
        app_state["active_music_track_file"] = ""
        app_state["music_owner"] = ""
        return False
    log.info("[LOUDNESS] Visualizer song reloaded at its scheduled position: %.1fs into %s",
             _seek, os.path.basename(str(_track)))
    return True


RELAUNCH_MAX_ATTEMPTS = 4
RELAUNCH_WINDOW_SEC = 600


# ============================================================================
# SECTION: Self-relaunch & update flow
# ============================================================================


def _build_relaunch_command():
    if getattr(sys, "frozen", False):
        _cmd = [sys.executable] + sys.argv[1:]
    else:
        _cmd = [sys.executable, os.path.abspath(__file__)] + sys.argv[1:]
    if "--relaunched" not in _cmd:
        _cmd.append("--relaunched")
    return _cmd


def _attempt_self_relaunch():
    import json
    _base_dir = os.path.dirname(os.path.abspath(sys.argv[0]))
    _watchdog_dir = os.path.join(_base_dir, "watchdog")
    os.makedirs(_watchdog_dir, exist_ok=True)
    _state_path = os.path.join(_watchdog_dir, "watchdog_relaunch_state.json")
    _now = time.time()

    try:
        try:
            with open(_state_path, "r", encoding="utf-8") as _f:
                _history = json.load(_f)
            if not isinstance(_history, list):
                _history = []
        except (FileNotFoundError, ValueError):
            _history = []

        _history = [t for t in _history if isinstance(t, (int, float)) and _now - t < RELAUNCH_WINDOW_SEC]

        if len(_history) >= RELAUNCH_MAX_ATTEMPTS:
            log.critical("[HEARTBEAT WATCHDOG] %d relaunches already in the last "
                         "%ds — holding off on another auto-relaunch (crash-loop "
                         "guard). See crash_log.txt for the stack dumps and "
                         "%s for the relaunch history.",
                         len(_history), RELAUNCH_WINDOW_SEC, _state_path)
            return False

        _history.append(_now)
        with open(_state_path, "w", encoding="utf-8") as _f:
            json.dump(_history, _f)
    except Exception as e:
        try:
            log.warning("[HEARTBEAT WATCHDOG] relaunch guard check failed (%s) — "
                        "skipping auto-relaunch to avoid an unguarded crash-loop.", e)
        except Exception:
            pass
        return False

    try:
        _cmd = _build_relaunch_command()
        _popen_kwargs = {
            "close_fds": True,
            "cwd": _base_dir,
        }
        if sys.platform == "win32":
            _popen_kwargs["creationflags"] = (
                getattr(subprocess, "DETACHED_PROCESS", 0x00000008)
                | getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0x00000200)
                | getattr(subprocess, "CREATE_BREAKAWAY_FROM_JOB", 0x01000000)
            )
        subprocess.Popen(_cmd, **_popen_kwargs)
        log.critical("[HEARTBEAT WATCHDOG] Spawned replacement process: %s", _cmd)
        return True
    except Exception as e:
        try:
            log.critical("[HEARTBEAT WATCHDOG] auto-relaunch spawn failed: %s", e)
        except Exception:
            pass
        return False


def _update_base_dir():
    if db is not None and getattr(db, "base_dir", None):
        return db.base_dir
    return os.path.dirname(os.path.abspath(sys.argv[0]))


def _set_update_result(result):
    """Copy updater output into the main-thread-owned UI state."""
    if not isinstance(result, dict):
        return
    if result.get("available"):
        app_state["_update_available"] = True
        app_state["_update_status"] = result.get("message", "Update available.")
        log.info("[UPDATE] %s", app_state["_update_status"])
    elif result.get("error"):
        app_state["_update_status"] = result["message"]
        log.warning("[UPDATE] %s", app_state["_update_status"])
    elif result.get("message"):
        app_state["_update_status"] = result["message"]
        log.info("[UPDATE] %s", app_state["_update_status"])


def _start_update_check():
    """Manual update check: fetches the manifest and stages a package without replacing files until Install Update is pressed again."""
    if app_state.get("_update_check_inflight", False):
        return
    app_state["_update_check_inflight"] = True
    app_state["_update_status"] = "Checking for updates..."
    base_dir = _update_base_dir()
    config = dict(db.config) if db is not None else {}

    def _worker():
        try:
            result = auto_updater.stage_available_update(base_dir, config=config)
            if result.get("staged"):
                app_state["_update_record"] = result["staged"]
                app_state["_update_ready"] = True
                app_state["_update_available"] = True
            _set_update_result(result)
        except Exception as exc:
            app_state["_update_status"] = f"Update check failed: {exc}"
            log.warning("[UPDATE] %s", app_state["_update_status"])
        finally:
            app_state["_update_check_inflight"] = False

    threading.Thread(target=_worker, daemon=True, name="ManualUpdateCheck").start()


def _launch_staged_update():
    record = app_state.get("_update_record")
    if not record:
        _start_update_check()
        return False
    try:
        helper_pid = auto_updater.launch_staged_update(
            _update_base_dir(),
            record,
            _build_relaunch_command(),
            parent_pid=os.getpid(),
        )
        app_state["_update_status"] = f"Installing update (helper {helper_pid})..."
        log.info("[UPDATE] Helper started: pid=%s version=%s",
                 helper_pid, record.get("version", "?"))
        pygame.event.post(pygame.event.Event(pygame.QUIT))
        return True
    except Exception as exc:
        app_state["_update_status"] = f"Could not start installer: {exc}"
        log.warning("[UPDATE] %s", app_state["_update_status"])
        return False


# ============================================================================
# SECTION: Watchdogs
# ============================================================================


def _force_recover_from_dead_main_loop(stalled_ms):
    try:
        import traceback as _tb
        _crash_path = os.path.join(_log_output_dir(), "crash_log.txt")
        with open(_crash_path, "a", encoding="utf-8") as _f:
            _f.write(f"\n=== MAIN LOOP FREEZE DETECTED {datetime.datetime.now().isoformat()} "
                     f"(heartbeat silent for {stalled_ms}ms) ===\n")
            for _thread_id, _frame in sys._current_frames().items():
                _f.write(f"\n--- Thread {_thread_id} ---\n")
                _tb.print_stack(_frame, file=_f)
    except Exception:
        pass

    try:
        log.critical("[HEARTBEAT WATCHDOG] Main loop heartbeat silent for "
                      "%dms (>= %dms threshold) — main thread appears wedged. "
                      "Forcing process exit for auto-relaunch.",
                      stalled_ms, HEARTBEAT_WATCHDOG_TIMEOUT_MS)
    except Exception:
        pass

    _attempt_self_relaunch()

    _hard_exit_process(1)


def _make_heartbeat_watchdog_tick():
    """Detects a wedged main loop (heartbeat not ticking) and force-exits the process for auto-relaunch."""
    def _tick():
        if _app_shutting_down.is_set():
            return
        now_ticks = pygame.time.get_ticks()
        hb_last = app_state.get("_heartbeat_last_ticks", now_ticks)
        stalled_ms = now_ticks - hb_last
        if stalled_ms >= HEARTBEAT_WATCHDOG_TIMEOUT_MS:
            if _app_shutting_down.is_set():
                return
            _force_recover_from_dead_main_loop(stalled_ms)
            return
    return _tick


def _vlc_log_writer_loop():
    f = None
    while True:
        line_text = _vlc_log_queue.get()
        try:
            path = VLC_DEBUG_LOG_PATH
            if not path:
                continue
            if f is None:
                f = open(path, "a", encoding="utf-8", errors="ignore")
            f.write(line_text + "\n")
            f.flush()
        except Exception:
            try:
                if f is not None:
                    f.close()
            except Exception:
                pass
            f = None


def _vlc_log_size_probe_worker(path, result_box):
    try:
        result_box[0] = os.path.getsize(path)
    except FileNotFoundError:
        result_box[0] = "missing"
    except Exception:
        result_box[0] = None


def _vlc_get_time_safe():
    """Best-effort read of the live engine's decode position in ms, or None."""
    # WARNING: callers must treat None as unknown, never as stalled.
    try:
        if vlc_engine is None or getattr(vlc_engine, "player", None) is None:
            return None
        pos = vlc_engine.player.get_time()
        return pos if isinstance(pos, (int, float)) and pos >= 0 else None
    except Exception:
        return None


def _make_vlc_log_watchdog_tick():
    """Warns when vlc-debug.log goes quiet while the playback position has stopped advancing."""
    # WARNING: a quiet vlc-debug.log alone is not a stall; if the playback position is still advancing, reset the tracker and do not warn.
    _state = {
        "last_size": None,
        "last_growth_ticks": pygame.time.get_ticks(),
        "last_warned_ticks": None,
        "probe_result": [None],
        "probe_inflight": False,
        "path_first_seen_ticks": None,
        "warned_missing": False,
        "last_pos_ms": None,
        "last_pos_change_ticks": pygame.time.get_ticks(),
    }
    _MISSING_FILE_GRACE_MS = 15000

    def _tick():
        path = VLC_DEBUG_LOG_PATH
        if not path:
            return
        if _state["path_first_seen_ticks"] is None:
            _state["path_first_seen_ticks"] = pygame.time.get_ticks()

        now_ticks_pos = pygame.time.get_ticks()
        cur_pos_ms = _vlc_get_time_safe()
        _position_advancing = False
        if cur_pos_ms is not None:
            if _state["last_pos_ms"] is None or cur_pos_ms != _state["last_pos_ms"]:
                _position_advancing = True
                _state["last_pos_ms"] = cur_pos_ms
                _state["last_pos_change_ticks"] = now_ticks_pos
        _position_known_stalled = (
            cur_pos_ms is not None
            and not _position_advancing
            and (now_ticks_pos - _state["last_pos_change_ticks"]) >= VLC_LOG_STALL_WARN_MS
        )

        if not _state["probe_inflight"]:
            _state["probe_result"][0] = None
            _state["probe_inflight"] = True
            threading.Thread(target=_vlc_log_size_probe_worker,
                              args=(path, _state["probe_result"]),
                              daemon=True).start()
            return

        size = _state["probe_result"][0]
        _state["probe_inflight"] = False

        if size == "missing":
            now_ticks = pygame.time.get_ticks()
            since_known_ms = now_ticks - _state["path_first_seen_ticks"]
            if since_known_ms >= _MISSING_FILE_GRACE_MS and not _state["warned_missing"]:
                _state["warned_missing"] = True
                log.warning(
                    "[VLC LOG WATCHDOG] vlc-debug.log has not been "
                    "created at all, %dms after VLC initialized (path=%s). "
                    "Expected it to exist by now via VLCEngineWrapper's "
                    "boot-marker write -- check the 'VLC log path = ...' "
                    "line(s) logged to app_log.txt at boot for which "
                    "logging path (callback / native fallback / "
                    "unavailable) was actually selected, and whether the "
                    "log directory itself is writable.",
                    since_known_ms, path)
            return

        if size is None:
            return

        _state["warned_missing"] = False

        now_ticks = pygame.time.get_ticks()
        if size != _state["last_size"]:
            _state["last_size"] = size
            _state["last_growth_ticks"] = now_ticks
            _state["last_warned_ticks"] = None
            return

        if not app_state.get("is_playing_video", False):
            _state["last_growth_ticks"] = now_ticks
            _state["last_warned_ticks"] = None
            return

        if cur_pos_ms is not None and not _position_known_stalled:
            _state["last_warned_ticks"] = None
            return

        stalled_ms = now_ticks - _state["last_growth_ticks"]
        _due_to_warn = (_state["last_warned_ticks"] is None
                         or (now_ticks - _state["last_warned_ticks"]) >= VLC_LOG_STALL_WARN_MS)
        if stalled_ms >= VLC_LOG_STALL_WARN_MS and _due_to_warn:
            _state["last_warned_ticks"] = now_ticks
            _watchdog_log_ch_raw = str(app_state.get("_live_playback_channel", "") or "").strip()
            _watchdog_log_ch = _watchdog_log_ch_raw.zfill(2) if _watchdog_log_ch_raw else app_state.get("current_channel")
            _corroboration = ("decode position also flat" if cur_pos_ms is not None
                               else "no live decode position available to corroborate")
            log.warning(
                "[VLC LOG WATCHDOG] vlc-debug.log has not grown in %dms "
                "while channel=%s is actively playing video (%s) -- "
                "libVLC's own --file-logging write may be stalled (same "
                "signature as a confirmed real freeze, where this file "
                "was cut off mid-line at the same moment the app "
                "heartbeat also went silent). Usually means the "
                "underlying drive itself is not responding, not just "
                "this app.",
                stalled_ms, _watchdog_log_ch, _corroboration)

    return _tick


def _background_watchdog_scheduler():
    """Single shared thread driving the heartbeat, VLC log and guide-preload watchdog checks off one 1 s tick."""
    # WARNING: an unwrapped exception in any one check would take all three down; keep each check wrapped.
    _heartbeat_tick = _make_heartbeat_watchdog_tick()
    _vlc_log_tick = _make_vlc_log_watchdog_tick()
    _guide_preload_tick = _make_guide_preload_watchdog_tick()

    _checks = (
        ("heartbeat", 5.0, _heartbeat_tick, "_heartbeat_watchdog_loop"),
        ("vlc_log", 5.0, _vlc_log_tick, "_vlc_log_watchdog_loop"),
        ("guide_preload", 1.0, _guide_preload_tick, "_guide_preload_watchdog"),
    )
    _next_due = {name: 0.0 for name, *_ in _checks}

    while True:
        if _app_shutting_down.wait(1.0):
            return
        _now = time.monotonic()
        for _name, _interval, _fn, _label in _checks:
            if _now < _next_due[_name]:
                continue
            _next_due[_name] = _now + _interval
            try:
                _fn()
            except Exception as e:
                try:
                    log.warning("%s: iteration failed: %s", _label, e)
                except Exception:
                    pass


